 if(browser){try{const query=new URL(location.href).searchParams.get('lang'),saved=localStorage.getItem('fantasy-language');current=['th','en'].includes(query)?query:['th','en'].includes(saved)?saved:navigator.language?.startsWith('th')?'th':'en'}catch(e){}}
 function trie(rows){const buckets=new Map();for(const [key,value]of rows){const prefix=key.slice(0,4);if(!buckets.has(prefix))buckets.set(prefix,[]);buckets.get(prefix).push([key,value])}for(const bucket of buckets.values())bucket.sort((a,b)=>b[0].length-a[0].length);return buckets}
