 function register(s){if(!s)return;const list=[s.name,s.givenName,s.surname,s.partner,s.household?.surname,s.pet?.name,...(s.household?.members||[]).map(x=>x.name),...(s.diary?.people||[]).map(x=>x.name),...(s.bonds?.cast||[]).map(x=>x.name),...(s.diary?.entries||[]).flatMap(e=>[e.guest?.name,e.visual?.guest?.name,...(e.visual?.cast||[]).map(x=>x.name)])];let changed=false;for(const name of list)if(typeof name==='string'&&thai.test(name)&&!names.has(name)){names.set(name,roman(name));for(const part of name.split(' '))if(part.length>2)names.set(part,roman(part));changed=true}if(changed){nameTree=trie(names);cache.clear()}}
 function english(value){const input=String(value??'');if(!thai.test(input))return input;if(cache.has(input))return cache.get(input);let output='';for(let i=0;i<input.length;){if(!thai.test(input[i])){output+=input[i++];continue}const found=match(nameTree,input,i)||match(words,input,i);if(found){if(/[A-Za-z0-9]$/.test(output)&&/^[A-Za-z]/.test(found.value))output+=' ';output+=found.value;i=found.end;if(/[A-Za-z0-9]$/.test(output)&&/[A-Za-z0-9]/.test(input[i]||''))output+=' '}else{let end=i+1;while(end<input.length&&thai.test(input[end])&&!match(words,input,end)&&!match(nameTree,input,end))end++;const missing=input.slice(i,end);unknown.add(missing);output+=missing;i=end}}output=output.replace(/\byears\s+(\d{3,})\b/g,'Year $1').replace(/(\d)years\b/g,'$1 years');if(cache.size>=6000)cache.clear();cache.set(input,output);return output}
