 function cast(s,p){const kin=p.familyCast?FamilyWorld.list(s).filter(m=>m.alive&&Engine.ageEquivalent(FamilyWorld.age(s,m),m.race)>=16):[];const selected=kin.find(m=>m.id==='guardian')||kin[0];if(selected)return {name:selected.name,memberId:selected.id,role:p.castRole};const race=p.id==='goblin-treaty'?0:s.race;return {name:FantasyNames.generate(s.seed,race,s.kingdom,700+catalog.findIndex(x=>x.id===p.id)*7).full,memberId:null,role:p.castRole||'ผู้ร่วมโครงการ'}}
 function start(s,id){const option=available(s).find(p=>p.id===id);if(!option?.available)return false;const p=byId.get(id),state=ensure(s),paused=state.paused.find(a=>a.id===id);if(paused){state.active=paused;state.paused=state.paused.filter(a=>a.id!==id);state.active.lastQuarter=count(s);state.active.lastBio=bio(s);state.active.lastNote=-1;history(s,'กลับมาทำต่อ: '+p.name);write(s,'กลับมาที่เป้าหมายเดิม: '+p.name,['คุณเปิดบันทึกที่พักไว้ในบท “'+p.stages[paused.stage].title+'” การเลือกและความคืบหน้าที่ผ่านมายังอยู่','เวลาที่พักไม่ได้สร้างความคืบหน้าหรือรางวัลย้อนหลัง คุณเริ่มกันเวลาให้เรื่องนี้จากวันนี้'],p.stages[paused.stage].scene);return true}state.active={id,kingdom:p.requirements.business?s.livelihood.business.kingdom:s.kingdom,stage:0,progress:0,lastQuarter:count(s),lastBio:bio(s),startedAge:s.age,cast:cast(s,p),decisions:[],attempts:0,lastNote:-1};history(s,'เริ่มเป้าหมาย: '+p.name);write(s,'เป้าหมายที่คุณเลือก: '+p.name,[p.description,state.active.cast.name+'จะร่วมเดินเรื่องนี้กับคุณ คุณยังต้องจัดเวลาให้ตรงกับแผน และรอให้การฝึกพาไปถึงการตัดสินใจแต่ละช่วง'],p.scene);return true}
