  if(!success&&a.attempts<2){a.attempts++;a.progress=.5;s.seen=s.seen.filter(id=>id!==event.id);delete s.flags[event.id];history(s,'ทบทวนบท '+(a.stage+1)+' ของ '+p.name);return true}
