'use strict';
(()=>{
 const H=HumanOrigins,labels={gold:'ทอง',health:'สุขภาพ',joy:'ความสุข',power:'พละกำลัง',magic:'เวท',wisdom:'ปัญญา',bond:'สายสัมพันธ์',fame:'ชื่อเสียง',clanFavor:'ความไว้ใจของตระกูล'};
 const C=(label,effect,success,extra={})=>({label,effect,success,risk:0,hint:Object.entries(effect).filter(([k])=>labels[k]).map(([k,v])=>labels[k]+' '+(v>0?'+':'')+v).join(' · '),...extra});
 const add=(id,title,text,min,choices,tags={})=>ev('human-'+id,title,text,choices,min,{humanOnly:true,once:true,lifeOpportunity:true,certain:true,...tags});
 add('road','ชีวิตที่อยากลองเป็นของตัวเอง','คนในบ้านเริ่มถามถึงอนาคต คุณอาจสืบงานของสกุล หรือเริ่มจากสิ่งที่อยากลองเอง ยังเปลี่ยนเส้นทางภายหลังได้',12,H.paths.map(p=>C(p.name,{},'คุณเลือกเริ่มเรียนรู้เรื่อง'+p.name+' โดยยังไม่ต้องตอบว่าชีวิตทั้งหมดจะจบที่ไหน',{humanPath:p.id,hint:p.description})),{max:25,humanPickPath:true,scene:'garden'});
 const houseDilemmas={
 crown:['ฎีกาที่มาถึงโต๊ะมงกุฎ','ชาวบ้านขอเลื่อนภาษีหลังผลผลิตเสียหาย ผู้ดูแลพระคลังเตือนว่าค่าจ้างทหารก็ถึงกำหนด',[
 ['จ่ายเงินส่วนตัวชดเชยภาษีช่วงนี้',{gold:-24,bond:8,fame:6,clanFavor:-4},'ครัวเรือนได้เวลาฟื้นนา ผู้ดูแลพระคลังขอให้คุณคิดแผนของฤดูถัดไปด้วย'],['เปิดบัญชีให้สภาเลือกส่วนที่เลื่อนได้',{wisdom:8,fame:4,clanFavor:2},'สภายอมตัดงานพิธีบางส่วนเพื่อจ่ายค่าจ้างและพักภาษี'],['รักษากำหนดแต่แบ่งชำระหลายงวด',{gold:12,bond:-3,clanFavor:6},'เงินยังเข้าพระคลัง แต่บางบ้านต้องขายของก่อนส่งงวดแรก']]],
 royal:['ชื่อบนหนังสือสู่ขอ','ญาติอยากให้คุณหมั้นเพื่อรักษาสิทธิในที่ดิน ทั้งที่คุณยังอยากใช้ชีวิตตามทางที่เลือก',[
 ['ขอรู้จักเจ้าตัวก่อนให้คำตอบ',{bond:5,wisdom:4,clanFavor:2},'อีกฝ่ายยอมคุยโดยไม่มีญาติร่วมโต๊ะ คุณได้ฟังว่าเขาเองอยากทำอะไร'],['ปฏิเสธแล้วหาเลี้ยงตนเอง',{joy:9,gold:-12,clanFavor:-8},'เงินช่วยจากบ้านลดลง แต่ตารางชีวิตเป็นสิ่งที่คุณกำหนดได้เอง'],['รับหน้าที่ตัวแทนสกุลโดยไม่หมั้น',{fame:6,bond:2,clanFavor:4},'ญาติยอมให้คุณรับงานเจรจาแทนเรื่องแต่งงาน คราวนี้ต้องเตรียมตัวจริงจัง']]],
 sovereign:['ข้อตกลงที่กษัตริย์อยากให้ลงชื่อ','ราชสำนักขอให้เครือข่ายของบ้านส่งเสบียงเข้าทัพ แต่คำสั่งนี้จะทำให้เมืองคู่ค้าขาดอาหาร',[
 ['กันเสบียงเลี้ยงเมืองก่อนส่งส่วนที่เหลือ',{gold:-18,bond:8,clanFavor:3},'บ้านยอมเสียรายได้บางส่วน เมืองคู่ค้ายังรับเรือของคุณต่อ'],['ต่อรองให้สภาทั้งสองฝ่ายกำหนดโควตา',{wisdom:8,fame:6,clanFavor:2},'ตราราชสำนักอยู่ข้างตราตระกูลในสัญญา ไม่มีฝ่ายใดสั่งเพียงลำพัง'],['รับสัญญากองทัพตามจำนวนเดิม',{gold:35,bond:-8,fame:-3,clanFavor:7},'คลังของบ้านมีเงินเพิ่ม ส่วนพ่อค้ารายเล็กเริ่มหาเส้นทางที่ไม่ผ่านคุณ']]],
 noble:['รายงานจากคนบนที่ดิน','ผู้ดูแลเสนอขับผู้เช่าที่ค้างค่าเช่าออกก่อนฤดูหว่าน ครอบครัวหนึ่งขอให้คุณมาดูด้วยตนเอง',[
 ['พักค่าเช่าและช่วยซื้อเมล็ด',{gold:-18,bond:8,clanFavor:-3},'คนในบ้านผู้เช่ากลับลงแปลง ชื่อคุณถูกเขียนข้างรายการเมล็ดที่ยืม'],['ไปตรวจบัญชีพร้อมตัวแทนผู้เช่า',{wisdom:8,fame:4,clanFavor:2},'พบค่าธรรมเนียมซ้ำในสมุด ผู้ดูแลต้องคืนส่วนที่เก็บเกิน'],['แบ่งที่บางส่วนให้ผู้เช่าจัดการเอง',{gold:-10,bond:5,fame:5,clanFavor:-5},'รายได้ของบ้านลดลง แต่ชาวบ้านเริ่มลงทุนกับแปลงที่ตัดสินใจเองได้']]],
 knight:['คำสั่งกับคนที่ยังไม่กลับ','ป้อมเรียกกำลังของสกุลกลับพร้อมกัน แต่ยังมีชาวบ้านติดอยู่อีกฟากสะพาน',[
 ['อยู่ช่วยพาคนกลับก่อน',{health:-5,bond:9,fame:5,clanFavor:-3},'คุณกลับช้ากว่าคำสั่ง คนที่ข้ามมาทันช่วยกันชี้แจงให้ป้อมฟัง'],['ขอกำลังอาสาโดยส่งข่าวกลับก่อน',{wisdom:6,power:3,clanFavor:4},'ป้อมจัดคนรับช่วง คุณได้พากลุ่มสุดท้ายข้ามก่อนคืนมืด'],['ทำตามคำสั่งแล้วจัดเสบียงรอ',{gold:-8,bond:3,clanFavor:6},'คุณกลับป้อมพร้อมถุงยา ฝากหน่วยที่ยังอยู่ให้นำไปส่งต่อ']]],
 mage:['ตำราที่บ้านไม่เคยเปิดให้คนนอก','ศิษย์ต่างเผ่าต้องการสูตรเวทพื้นฐานเพื่อรักษาคนในบ้าน แต่ญาติถือว่าเป็นความลับของสกุล',[
 ['แบ่งบทพื้นฐานที่ช่วยรักษาได้',{magic:5,bond:8,clanFavor:-6},'ศิษย์กลับมารายงานอาการคนไข้ และคืนตำราพร้อมบันทึกข้อผิดพลาด'],['ทำฉบับสอนใช้โดยไม่เปิดวงหลัก',{wisdom:7,magic:3,clanFavor:4},'คนเรียนใช้เวทได้โดยไม่ต้องรับความลับที่ยังควบคุมไม่ไหว'],['ออกค่ายารักษาโดยไม่มอบตำรา',{gold:-16,bond:5,clanFavor:3},'คนไข้ได้รับยา แต่คุณยังต้องกลับมาคิดเรื่องสิทธิเรียนของศิษย์']]],
 merchant:['คำสั่งซื้อกับเงินค่าจ้าง','สินค้าล็อตใหญ่ขายไม่ออก คู่ค้าขอให้เลื่อนค่าจ้างคนขนของเพื่อรักษาทุนร้าน',[
 ['จ่ายค่าจ้างก่อนแล้วรับกำไรน้อยลง',{gold:-20,bond:8,clanFavor:-2},'คนขนของกลับมารับเที่ยวใหม่ แม้ร้านยังต้องรอขายสินค้าค้าง'],['แบ่งขายล็อตเล็กกับร้านเพื่อนบ้าน',{wisdom:7,gold:10,clanFavor:4},'เงินหมุนกลับช้ากว่าเดิม แต่ร้านเล็กช่วยกระจายสินค้าจนคลังโล่ง'],['เจรจาตารางจ่ายต่อหน้าคนงาน',{bond:4,wisdom:4,clanFavor:3},'ทุกคนเห็นจำนวนที่ต้องรอและวันที่จ่าย ส่วนที่จำเป็นถูกจ่ายก่อน']]],
 artisan:['ชื่อช่างบนงานชิ้นเดียว','กิลด์อยากซื้อแบบของบ้านแล้วประทับชื่อร้านใหญ่ คุณกับญาติทำงานชิ้นนี้ด้วยกันหลายเดือน',[
 ['ขายโดยเก็บชื่อช่างทุกคนไว้',{gold:20,fame:5,clanFavor:4},'ป้ายใต้ชิ้นงานมีชื่อคนที่ลงมือครบ คนฝึกหัดเปิดดูซ้ำหลายรอบ'],['เก็บแบบแล้วรับผลิตเอง',{gold:-12,wisdom:6,clanFavor:5},'งานโตช้าลง แต่ลูกค้ารายแรกได้คุยกับคนสร้างของให้เขาจริง ๆ'],['เปิดแบบแลกกับสิทธิขายงานสอน',{bond:6,fame:5,clanFavor:-2},'คนอื่นซ่อมของตามแบบได้ และเริ่มมาขอเรียนจากบ้านคุณ']]],
 agrarian:['เมล็ดที่ต้องเลือกเก็บ','เมล็ดพันธุ์เหลือพอให้หว่านทั้งแปลง หรือแบ่งส่วนหนึ่งขายเอาเงินมาซ่อมหลังคา',[
 ['ขายบางส่วนแล้วหว่านแปลงเล็กลง',{gold:14,joy:-2,clanFavor:3},'หลังคากันฝนได้ ปีนี้ผลผลิตน้อยลงแต่ไม่มีใครต้องย้ายที่นอน'],['ขอร่วมเมล็ดกับบ้านข้างแปลง',{bond:7,wisdom:4,clanFavor:4},'ทั้งสองบ้านตกลงแบ่งผลผลิตก่อนลงเมล็ด คนในบ้านช่วยกันซ่อมหลังคาทีหลัง'],['ใช้เงินเก็บซ่อมแล้วเก็บเมล็ดทั้งหมด',{gold:-14,health:2,clanFavor:5},'เงินในถุงเบาลง แต่เมล็ดรุ่นต่อไปยังอยู่กับบ้าน']]],
 ordinary:['งานเพิ่มกับมื้อเย็นที่นัดไว้','นายจ้างเสนอกะเพิ่มในวันที่คุณรับปากว่าจะกลับไปกินข้าวกับคนในบ้าน',[
 ['รับกะเพิ่มและบอกคนที่บ้านก่อน',{gold:14,joy:-2,bond:-2,clanFavor:1},'คุณกลับมาพบหม้อที่เก็บไว้ให้ คนในบ้านถามว่าเหนื่อยมากไหม'],['กลับตามนัดแล้วหางานวันอื่น',{joy:5,bond:7,clanFavor:4},'คุณเล่าเรื่องค่าจ้างระหว่างมื้อ ทุกคนช่วยกันคิดว่าจะลดค่าใช้จ่ายส่วนไหน'],['ขอรับเพียงครึ่งกะ',{gold:6,bond:3,clanFavor:2},'คุณมาถึงช้าหน่อย แต่ยังได้นั่งกินด้วยกันก่อนเก็บโต๊ะ']]]
 };
 for(const house of H.clans){const d=houseDilemmas[house.type];add('house-'+house.id,d[0]+' · '+house.name,'บ้านสกุล'+house.name+'มีคติว่า “'+house.motto+'” '+d[1],18,d[2].map(x=>C(...x)),{max:85,clanOnly:house.id,scene:['crown','royal','sovereign','noble'].includes(house.type)?'council':house.type==='mage'?'library':house.type==='knight'?'barracks':house.type==='agrarian'?'farm':house.type==='merchant'?'market':'kitchen'});}
 for(const culture of H.cultures){add('culture-'+culture.id,'ธรรมเนียมที่คุณเริ่มจำได้ · '+culture.name,'ที่บ้าน'+culture.custom+' เพื่อนที่มาวันนี้ไม่รู้ว่าควรเริ่มตรงไหน',6,[C('ชวนเพื่อนลองทำไปด้วยกัน',{bond:5,joy:2},'เพื่อนทำพลาดตรงเดียวกับคุณครั้งแรก คนในบ้านหัวเราะแล้วช่วยสอนอีกครั้ง'),C('เล่าให้ฟังก่อนแล้วให้เขาเลือก',{wisdom:4,bond:3},'เพื่อนถามว่าธรรมเนียมนี้เริ่มมาจากอะไร ผู้เฒ่าจึงเล่าเรื่องที่คุณยังไม่เคยรู้'),C('ลองผสมธรรมเนียมของสองบ้าน',{joy:5,wisdom:2},'มื้อวันนี้ไม่เหมือนปีไหน แต่ทุกคนมีส่วนที่คุ้นเคยอยู่บนโต๊ะ')],{max:12,ethnicityOnly:culture.id,scene:'kitchen'});
 add('culture-adult-'+culture.id,'ภาษาที่อยากส่งต่อ · '+culture.name,'เด็กในย่านเริ่มไม่คุ้นกับ'+culture.language+' คนในบ้านอยากให้คุณช่วยเก็บเรื่องเล่าและชื่ออาหารอย่าง'+culture.food,22,[C('ชวนผู้เฒ่ากับเด็กเล่าร่วมกัน',{bond:7,wisdom:5},'เด็กเลือกจดคำที่ใช้ในชีวิตจริง ส่วนผู้เฒ่าได้ยินเรื่องใหม่จากเด็กบ้าง'),C('ทำสมุดสองภาษาแจกในย่าน',{gold:-12,wisdom:7,fame:3},'สมุดไม่ได้แทนบทสนทนา แต่ทำให้คนต่างบ้านเริ่มถามคำที่ไม่เคยกล้าถาม'),C('เก็บเรื่องของบ้านไว้เล่าระหว่างมื้อ',{joy:5,bond:6},'คนในบ้านเริ่มถามหาชื่อเดิมของอาหารก่อนช่วยกันทำ')],{max:85,ethnicityOnly:culture.id,scene:'library'});}
 const arcs={
 adventure:[
 ['งานแรกนอกกำแพง','กิลด์มีงานสำรวจทางเก่า ค่าจ้างไม่สูงและทีมยังไม่เคยออกเดินทางด้วยกัน',[['ซื้ออุปกรณ์ร่วมแล้วเริ่มเส้นสั้น',{gold:-10,power:5,bond:4},'ทุกคนกลับมาพร้อมแผนที่แผ่นเล็กและเรื่องเล่าเต็มโต๊ะ'],['ฝึกกับทีมก่อนรับงานจริง',{wisdom:6,power:3},'คุณรู้แล้วว่าใครควรนำทางและใครควรเฝ้าเวร'],['รับงานคุ้มกันใกล้เมืองไปก่อน',{gold:12,health:-2},'ค่าจ้างก้อนแรกไม่ได้มาจากสมบัติ แต่จากการพาคนกลับถึงบ้าน']]],
 ['หีบกับเพื่อนที่เดินไม่ไหว','ทีมพบหีบในซากเมือง แต่เพื่อนร่วมทางขาเจ็บก่อนถึงทางออก',[['จ้างคนเพิ่มแล้วพากลับพร้อมกัน',{gold:-18,bond:8,fame:4},'หีบถูกแบ่งตามสัญญา และเพื่อนกลับมานั่งร่วมโต๊ะได้อีก'],['ทิ้งหีบแล้วพาเพื่อนกลับ',{health:-4,bond:10},'ไม่มีของมีค่ากลับกิลด์ แต่ชื่อทุกคนยังถูกขีดว่าเดินทางกลับแล้ว'],['ฝากหีบไว้แล้วทำแผนที่กลับมา',{wisdom:8,power:3},'คุณเลือกทางที่ต้องใช้ความอดทนมากกว่าความเร็ว']]],
 ['ทีมที่มีคนอยากตามคุณไป','กิลด์ขอให้คุณนำผู้ฝึกหัดออกเดินทาง คุณจำงานแรกของตัวเองได้',[['พาไปเส้นสั้นและสอนทางกลับ',{bond:8,fame:6},'ผู้ฝึกหัดส่งแผนที่ให้คุณตรวจ ก่อนชวนกันไปรับงานรอบใหม่'],['เขียนคู่มือจากบันทึกจริง',{wisdom:10,gold:12},'คู่มือมีรอยที่คุณเคยเดินผิด คนอ่านจึงรู้ว่าควรระวังตรงไหน'],['เก็บทีมเล็กและรับงานเท่าที่ไหว',{health:6,joy:7},'คุณยังเดินทาง แต่มีวันกลับมากินมื้อเย็นที่บ้านบ่อยขึ้น']]]],
 farmer:[
 ['ฤดูแรกที่ได้ตัดสินใจเอง','บ้านให้คุณดูแลแปลงเล็ก จะหว่านพืชราคาแพงหรือพืชที่กินได้แม้ขายไม่หมด',[['ปลูกพืชกินได้หลายชนิด',{gold:-7,wisdom:6,health:3},'แม้ขายได้ไม่มาก โต๊ะที่บ้านก็มีผักจากแปลงคุณ'],['ร่วมเมล็ดพันธุ์กับแปลงข้าง ๆ',{gold:-5,bond:6,wisdom:3},'คุณเรียนรู้ว่าดินสองฝั่งคันนาเก็บน้ำไม่เหมือนกัน'],['รับดูแลแปลงของคนอื่นเพื่อเรียนก่อน',{gold:10,wisdom:4},'ค่าจ้างไม่มาก แต่ได้รู้วิธีที่คนในย่านทำกันมาหลายปี']]],
 ['ราคาหน้าลานรับซื้อ','ผลผลิตพร้อมกันทั้งย่าน ผู้รับซื้อกดราคาเพราะทุกบ้านต้องใช้เงินทันที',[['รวมรถขนไปขายตลาดเมือง',{gold:-12,wisdom:7,bond:5},'เงินกลับช้าหน่อย แต่บ้านที่ร่วมรถได้ส่วนแบ่งตามกระสอบจริง'],['แปรรูปส่วนหนึ่งไว้ขายทีหลัง',{gold:-8,joy:4,wisdom:5},'ครัวที่บ้านเต็มไปด้วยกลิ่นตากแห้ง คุณเริ่มมีลูกค้าประจำ'],['ขายพอใช้หนี้แล้วเก็บส่วนที่เหลือ',{gold:18,joy:-2},'หนี้งวดนี้จบลง คุณยังมีเวลาเลือกจังหวะขายส่วนที่เก็บไว้']]],
 ['แปลงที่คนรุ่นใหม่จะได้ใช้','คุณเริ่มคิดว่าจะส่งต่อดินและเมล็ดอย่างไรให้คนที่มาทำต่อ',[['แบ่งแปลงให้ผู้ฝึกหัดทดลอง',{bond:9,wisdom:5},'แปลงเล็กมีพืชหน้าตาใหม่ คุณได้เป็นคนถามว่าพวกเขาปลูกอะไร'],['ลงทุนพักดินและเก็บน้ำ',{gold:-24,health:4,fame:5},'ผลผลิตปีนี้ลดลง แต่ดินเริ่มเก็บน้ำได้ดีขึ้น'],['ทำสมุดฤดูกาลของบ้าน',{wisdom:10,bond:4},'คนในบ้านเปิดสมุดดูแม้ในวันที่คุณไม่ได้อยู่ที่แปลง']]]],
 artisan:[
 ['ของชิ้นแรกที่มีคนจ่ายเงินจริง','ลูกค้านำของที่ใช้ทุกวันมาให้ซ่อม คุณยังไม่มั่นใจว่าฝีมือพอหรือไม่',[['ซื้อวัสดุให้ตรงกับของเดิม',{gold:-8,wisdom:6},'รอยซ่อมยังมองเห็น แต่ลูกค้าใช้ของชิ้นนี้ต่อได้อีก'],['ทำกับช่างรุ่นพี่และแบ่งค่าจ้าง',{gold:6,bond:4,wisdom:3},'คุณได้รู้วิธีจับเครื่องมือที่ตำราไม่ได้บอก'],['เริ่มจากงานเล็กที่ทำได้แน่นอน',{gold:10,joy:3},'งานแรกส่งตรงเวลา ลูกค้าฝากชื่อคุณให้คนข้างบ้าน']]],
 ['งานเร่งก่อนวันสำคัญ','งานใหม่จ่ายดี แต่งานเก่าของลูกค้าประจำยังไม่เสร็จ',[['จ้างผู้ช่วยโดยแจ้งลูกค้าก่อน',{gold:-14,bond:5,wisdom:4},'งานเดินพร้อมกันได้ คุณได้ฝึกอธิบายให้คนอื่นรับช่วง'],['ทำงานเก่าให้จบแล้วปฏิเสธงานใหม่',{joy:5,fame:5},'รายได้ไม่เพิ่มรอบนี้ แต่ลูกค้ารู้ว่าเวลาที่นัดไว้เชื่อถือได้'],['ขอแบ่งส่งเป็นสองรอบ',{wisdom:7,bond:3},'ทั้งสองฝ่ายเห็นชิ้นงานจริงก่อนตกลงวันรับส่วนที่เหลือ']]],
 ['มืออีกคู่ข้างโต๊ะช่าง','คนหนุ่มสาวมาขอฝึกงาน เขาถามว่าต้องทำของเหมือนคุณทุกอย่างไหม',[['สอนพื้นฐานแล้วให้ลองแบบของเขา',{wisdom:8,bond:7},'ชิ้นงานของเขาดูต่างออกไป คุณจำความตื่นเต้นแบบนั้นได้'],['เก็บแบบเก่าไว้ในสมุดร่วม',{fame:5,wisdom:7},'มีคนเขียนต่อท้ายแบบของคุณว่าเปลี่ยนอะไรเพื่อให้ใช้ได้ดีขึ้น'],['ลดงานรับเพื่อทำของที่อยากทำ',{gold:-10,joy:10},'โต๊ะของคุณกลับมามีงานที่เริ่มจากความอยากลองอีกครั้ง']]]],
 merchant:[
 ['วันแรกที่อยู่หลังเคาน์เตอร์','เงินในลิ้นชักเป็นทั้งทุนซื้อของและเงินที่บ้านต้องใช้ คุณต้องแยกมันให้ได้',[['ทำสมุดสองเล่มแยกทุนกับเงินบ้าน',{wisdom:6,bond:3},'วันปิดร้านคุณรู้ว่ากำไรจริงเหลือเท่าไร'],['รับฝากขายจากเพื่อนก่อนซื้อสต็อก',{bond:6,gold:8},'ร้านยังเล็ก แต่สินค้าที่ขายมีเรื่องของคนทำอยู่ด้วย'],['เริ่มขายเพียงของที่รู้จักดี',{gold:10,joy:3},'คุณตอบคำถามลูกค้าได้โดยไม่ต้องเดา']]],
 ['เครดิตของลูกค้าประจำ','ครอบครัวที่ซื้อของร้านคุณมานานขอค้างจ่าย ขณะที่ผู้ส่งของเองก็รอเงิน',[['ออกเงินส่วนตัวช่วยเฉพาะของจำเป็น',{gold:-15,bond:8},'เขากลับมาจ่ายทีละน้อย และบอกตรง ๆ ว่าส่วนไหนยังไม่ไหว'],['ตกลงวงเงินกับวันจ่ายให้ชัด',{wisdom:7,bond:3},'ลูกค้าไม่ต้องหลบหน้าคุณเพื่อเลี่ยงคำถามที่ไม่มีคำตอบ'],['ช่วยหาร้านที่แบ่งจ่ายได้ในงบ',{bond:5,wisdom:4},'ร้านไม่ได้ขายทุกอย่าง แต่ลูกค้ายังกลับมาทักคุณ']]],
 ['ร้านที่เริ่มมีชื่อของตัวเอง','ลูกค้าจำร้านจากคนที่อยู่หลังเคาน์เตอร์ มากกว่าป้ายของตระกูล',[['เปิดสาขากับคนที่ฝึกมาด้วยกัน',{gold:-26,fame:7,bond:4},'ป้ายใหม่มีชื่อคนร่วมทำร้าน ไม่ใช่เพียงชื่อคุณ'],['รักษาร้านเล็กและเวลาของบ้าน',{joy:9,bond:6},'คุณปิดม่านตามเวลาและยังจำรายการโปรดของลูกค้าได้'],['แบ่งทุนให้ผู้ค้าเล็กในย่าน',{gold:-18,bond:9,fame:4},'ตลาดมีร้านใหม่เพิ่มขึ้น และคู่แข่งบางคนกลายเป็นคนกินข้าวด้วยกัน']]]],
 music:[
 ['เพลงแรกต่อหน้าคนอื่น','เวทีเล็กในงานชุมชนเหลือช่วงว่างหนึ่งเพลง คุณยังเล่นท่อนท้ายได้ไม่คล่อง',[['ซ้อมกับเพื่อนจนจบทั้งเพลง',{bond:5,joy:5},'มีเสียงผิดอยู่หนึ่งจุด แต่เพื่อนรับท่อนต่อจนเพลงจบ'],['เลือกเพลงสั้นที่รู้จักดี',{joy:6,fame:3},'คนดูร้องตามได้ คุณจำเสียงนั้นมากกว่าเสียงปรบมือ'],['เล่นให้คนโต๊ะข้างเวทีฟังก่อน',{bond:6,wisdom:3},'คนฟังบอกว่าท่อนที่ชอบคือท่อนที่คุณเกือบตัดทิ้ง']]],
 ['ค่าจ้างกับเพลงที่อยากเล่น','ร้านใหญ่ขอให้คุณเล่นเพลงเดิมทุกคืน รายได้แน่นอนแต่ไม่มีเวลาทำเพลงของตัวเอง',[['รับบางคืนแล้วเก็บวันแต่งเพลง',{gold:14,joy:5},'ตารางไม่เต็มทุกวัน สมุดเพลงเริ่มมีหน้าที่เขียนจนจบ'],['ออกทุนแสดงเพลงใหม่กับวงเล็ก',{gold:-18,fame:7,bond:5},'คนดูไม่มาก แต่มีคนรอถามว่าครั้งหน้าจะเล่นที่ไหน'],['เล่นงานประจำและแต่งหลังร้านปิด',{gold:24,health:-3,joy:-2},'คุณมีเงินเก็บเพิ่ม แต่เริ่มต้องเผื่อวันพักจริง ๆ']]],
 ['เพลงที่คนในบ้านจำได้','เด็กในย่านฮัมเพลงของคุณผิดไปหลายคำ คนที่บ้านบอกว่าได้ยินมาทั้งวัน',[['ชวนเด็กเล่นเวอร์ชันของเขา',{joy:9,bond:7},'เพลงเปลี่ยนไปนิดหน่อย และกลายเป็นเสียงของย่านนี้'],['บันทึกทำนองไว้ให้คนรุ่นต่อไป',{wisdom:7,fame:7},'โน้ตมีวันที่กับชื่อคนที่เล่นร่วมกันในครั้งแรก'],['จัดมื้อเล็กและเล่นให้คนใกล้ตัว',{gold:-10,bond:10},'ไม่มีเวทีหรือป้ายชื่อ แต่คุณได้ยินทุกคนร้องท่อนสุดท้ายพร้อมกัน']]]],
 mage:[
 ['บทเวทที่ช่วยงานเล็กได้','คุณควบคุมแสงดวงเล็กได้แล้ว ครูถามว่าจะใช้มันทำอะไรเป็นอย่างแรก',[['ทำโคมอ่านหนังสือให้บ้าน',{gold:-8,magic:6,bond:3},'คนในบ้านอ่านได้อีกนิดก่อนนอนโดยไม่ต้องฝืนตา'],['ฝึกปิดวงเวทให้ได้ทุกครั้ง',{magic:8,wisdom:3},'คุณใช้เวลามากกับการหยุดแสงพอ ๆ กับตอนทำให้มันติด'],['ไปช่วยช่างเวทในย่าน',{gold:10,magic:4},'งานแรกเป็นการเปลี่ยนวงที่ชำรุด คุณเรียนรู้ว่าความแม่นยำสำคัญเพียงใด']]],
 ['ผลทดลองที่ไม่ตรงตำรา','เวทในบันทึกของบ้านทำงานต่างออกไปเมื่อใช้กับคนต่างเผ่า',[['จ้างผู้รู้หลายเผ่ามาทดลองร่วมกัน',{gold:-20,wisdom:7,bond:5},'เงื่อนไขที่เคยซ่อนไว้ในคำว่าใช้ได้กับทุกคนถูกเขียนให้ชัด'],['เปิดบันทึกความผิดพลาดให้ตรวจ',{fame:5,wisdom:8,clanFavor:-3},'มีคนส่งวิธีแก้มาให้ พร้อมบันทึกว่าตนเคยพลาดแบบเดียวกัน'],['หยุดใช้บทนี้และกลับไปฝึกพื้นฐาน',{magic:6,health:4},'คุณยอมเลื่อนงานออกไปจนกว่าจะอธิบายสิ่งที่เกิดขึ้นได้']]],
 ['วิชาที่จะฝากไว้ในโลก','คุณเริ่มมีศิษย์ที่ถามว่าควรทำทุกอย่างให้เหมือนครูไหม',[['ให้ศิษย์ลองวิธีที่ตรวจผลได้เอง',{magic:6,wisdom:7,bond:5},'ห้องเรียนเต็มไปด้วยคำถามที่คุณเองต้องกลับไปค้นต่อ'],['เขียนตำราที่บอกข้อจำกัดครบ',{wisdom:10,fame:5},'ผู้อ่านรู้ทั้งสิ่งที่บทเวทช่วยได้และเวลาที่ควรหยุด'],['ใช้วิชาดูแลงานในย่านต่อ',{gold:18,bond:8},'เวทของคุณอยู่ในโคม ประตูน้ำ และชีวิตประจำวันของคนรอบบ้าน']]]],
 knight:[
 ['เวรแรกของหมู่บ้าน','คุณได้รับตราอาสาและตะเกียงสำหรับเดินตรวจ คนที่บ้านยืนส่งถึงปากซอย',[['เดินกับคนเวรเก่าแล้วจำชื่อบ้าน',{bond:5,wisdom:4},'คุณเริ่มรู้ว่าบ้านไหนมีคนแก่และใครยังทำงานดึก'],['ฝึกสัญญาณเรียกกำลังให้คล่อง',{power:6,wisdom:3},'คุณกับเพื่อนเวรแยกเสียงขอช่วยจากเสียงฝึกได้ทันที'],['รับเวรสั้นแล้วกลับมาทบทวน',{gold:9,health:3},'การคุ้มครองคืนแรกไม่มีการประลอง มีเพียงคนกลับถึงบ้านครบ']]],
 ['คนถืออาวุธที่วางมันลงแล้ว','ผู้ต้องสงสัยยอมวางดาบ แต่หัวหน้าขอให้คุณลงโทษเพื่อไม่ให้คนอื่นเอาอย่าง',[['พาเข้ากระบวนการสอบสวน',{wisdom:7,bond:5,clanFavor:-3},'คุณต้องเขียนรายงานยาวกว่าคนอื่น แต่ผู้ถูกจับได้เล่าเรื่องของตน'],['ขอให้ผู้บังคับบัญชาทวนคำสั่งต่อหน้าพยาน',{fame:6,wisdom:5},'คำสั่งเปลี่ยนเป็นให้คุมตัว คุณจำได้ว่าเสียงของตัวเองสั่นเพียงใด'],['เปลี่ยนไปคุ้มกันคนออกจากพื้นที่',{health:-2,bond:8},'คุณทำให้คนรอบข้างพ้นจากวงความโกรธก่อน แล้วจึงกลับมารายงาน']]],
 ['ตราที่เริ่มมีคนเชื่อใจ','ผู้ฝึกหัดถามว่าทำอย่างไรให้คนไม่กลัวเวลาคุณเดินเข้าย่าน',[['พาไปช่วยงานก่อนออกตรวจ',{bond:9,fame:5},'คนในตลาดเริ่มเรียกชื่อผู้ฝึกหัดก่อนเรียกตำแหน่ง'],['สอนด้วยเหตุการณ์ที่ตนเคยพลาด',{wisdom:8,bond:5},'ห้องฝึกเงียบเมื่อคุณเล่าถึงวันที่ไม่รู้ว่าควรทำอย่างไร'],['ลดเวรแล้วดูแลบ้านมากขึ้น',{health:7,joy:7},'คุณส่งตะเกียงให้คนเวรถัดไปและกลับทันมื้อเย็นบ่อยขึ้น']]]],
 scholar:[
 ['ชื่อที่เขียนได้เองครั้งแรก','คนในย่านมาขอให้คุณช่วยอ่านเอกสาร เขาอยากลงชื่อตนเองให้ได้',[['นั่งสอนทีละตัวจนเขียนครบ',{bond:6,wisdom:4},'ลายมือยังสั่น แต่เจ้าตัวขอเก็บกระดาษแผ่นแรกไว้'],['ทำแบบฝึกจากคำที่ใช้ทุกวัน',{wisdom:7,fame:2},'คำในบทเรียนเริ่มจากชื่อคนในบ้านและรายการของตลาด'],['อ่านให้ฟังแล้วนัดเรียนวันว่าง',{gold:8,bond:4},'เอกสารเสร็จวันนี้ ส่วนบทเรียนแรกเริ่มในวันหยุดของเขา']]],
 ['เรื่องที่ตำราไม่เคยใส่ชื่อ','บันทึกทางการเล่าเรื่องชัยชนะ แต่คนที่อยู่ในวันนั้นจำชื่อผู้หายไปได้',[['ฟังพยานหลายฝ่ายแล้วเก็บทุกฉบับ',{wisdom:9,bond:4},'บันทึกใหม่มีส่วนที่ยังไม่ตรงกัน และบอกชัดว่าใครเป็นผู้เล่า'],['พิมพ์ความทรงจำของคนในย่าน',{gold:-16,fame:6,bond:5},'เล่มเล็กถูกส่งต่อระหว่างบ้าน มีคนมาแก้การสะกดชื่อญาติของตน'],['เก็บหลักฐานไว้ให้คนรุ่นหลังค้นได้',{wisdom:8,joy:3},'คุณจัดที่มาและวันที่ครบ แม้ยังหาคำตอบทั้งหมดไม่ได้']]],
 ['โต๊ะเรียนที่ไม่ต้องมีคุณอยู่ตลอด','คนที่เคยขอให้ช่วยอ่านเริ่มสอนคนอื่นในย่านแล้ว',[['ส่งต่อชั้นเรียนแล้วช่วยจากด้านหลัง',{joy:6,bond:9},'คุณได้นั่งเป็นคนฟังคำถามที่ไม่ได้ถามถึงคุณเป็นคนแรก'],['สร้างคลังหนังสือร่วมกัน',{gold:-20,wisdom:7,fame:5},'หนังสือยืมได้ด้วยชื่อ ไม่ใช่ฐานะของคนยืม'],['เขียนเรื่องของบ้านตนเองบ้าง',{wisdom:8,joy:7},'คราวนี้ชื่อคนที่อยู่ในครัวปรากฏในเล่มด้วย ไม่ใช่เพียงชื่อคนในสภา']]]],
 healer:[
 ['วันแรกที่คนไข้จำชื่อคุณได้','ผู้รักษาให้คุณช่วยดูแลคนไข้ระหว่างรอ เขาถามว่าต้องกลัวอะไรบ้าง',[['ฟังอาการแล้วทวนกับผู้รักษา',{wisdom:6,bond:4},'คนไข้ไม่ต้องเล่าเรื่องเดิมใหม่ทั้งหมดเมื่อผู้รักษาเข้ามา'],['จัดน้ำ อาหาร และที่พักให้เหมาะ',{gold:-5,bond:6,health:2},'ญาติคนไข้ได้หยุดพักบ้าง และเริ่มถามวิธีช่วยดูแลต่อ'],['ฝึกงานที่รับผิดชอบได้ให้คล่อง',{gold:8,wisdom:5},'คุณรู้ว่าขั้นตอนไหนทำเองได้ และเมื่อไรต้องเรียกคนที่ชำนาญกว่า']]],
 ['ค่ายากับค่าเดินทางกลับบ้าน','คนไข้มีเงินพอซื้อยา หรือพาคนในบ้านกลับเมือง เขาถามว่าต้องเลือกอย่างไร',[['ช่วยออกส่วนที่ขาดจากเงินตน',{gold:-18,bond:8},'คนไข้ได้ยาครบพร้อมตั๋วกลับ คุณเก็บสำเนาวิธีใช้ไว้ให้ญาติ'],['หากองทุนและยาทางเลือกกับผู้รักษา',{wisdom:8,bond:5},'แผนรักษาใหม่อยู่ในงบและยังมีคนติดตามอาการ'],['ประสานรักษาต่อที่เมืองบ้านเกิด',{wisdom:6,fame:4},'คนไข้ไม่ต้องเริ่มเล่าใหม่ทั้งหมด เพราะบันทึกเดินทางไปพร้อมเขา']]],
 ['คืนที่ต้องยอมให้คนอื่นรับเวร','ห้องยายุ่งมากและคุณเริ่มจัดฉลากผิดที่ เพื่อนเวรขอให้พัก',[['ส่งเวรพร้อมรายงานที่ครบ',{health:8,wisdom:4},'คุณได้นอนจนเต็มตื่น และกลับมาเห็นคนไข้ยังมีคนดูแล'],['ฝึกผู้ช่วยให้รับช่วงงานพื้นฐาน',{bond:8,wisdom:6},'งานไม่ต้องรอคุณทุกขั้น คนไข้เรียกชื่อผู้ช่วยได้มากขึ้น'],['ลดงานแล้วเปิดตรวจใกล้บ้าน',{gold:-16,joy:7,bond:6},'คนในย่านได้ผู้รักษาที่มีเวลาฟัง และคุณมีเวลากลับไปกินข้าว']]]],
 home:[
 ['โต๊ะที่อยากให้มีทุกคน','เวลางานของคนในบ้านไม่ตรงกัน คุณอยากหามื้อที่ได้นั่งพร้อมหน้า',[['แบ่งเงินทำอาหารในวันว่าง',{gold:-7,bond:7,joy:3},'คนที่ปกติรีบออกจากโต๊ะได้นั่งเล่าเรื่องของตนจนจบ'],['ช่วยสลับงานบ้านให้มีเวลาตรงกัน',{bond:6,wisdom:4},'ตารางไม่ได้สมบูรณ์ทุกวัน แต่มีเย็นหนึ่งที่ทุกคนรอเหมือนกัน'],['เริ่มจากมื้อเล็กกับคนที่กลับก่อน',{joy:5,bond:4},'คุณอุ่นส่วนที่เหลือไว้ให้คนกลับช้า และนั่งเป็นเพื่อนเขาอีกนิด']]],
 ['บ้านข้าง ๆ ที่เงียบไป','เพื่อนบ้านไม่ออกมาตลาดหลายวัน คุณเห็นอาหารวางค้างที่หน้าประตู',[['เคาะประตูถามและนำอาหารไปให้',{gold:-6,bond:8},'เขาเปิดประตูช้า ๆ ก่อนเล่าว่าป่วยและไม่อยากรบกวนใคร'],['ชวนคนในย่านแบ่งเวรแวะดู',{bond:7,wisdom:4},'ไม่มีใครต้องรับทุกอย่างคนเดียว และเขาจำได้ว่าแต่ละวันจะมีใครมา'],['ช่วยติดต่อญาติที่อยู่ต่างเมือง',{wisdom:5,bond:5},'ญาติมาถึงพร้อมของใช้ คนในย่านยังแวะมาทักตามเดิม']]],
 ['สิ่งที่บ้านยังทำต่อ','คนในบ้านเริ่มทำอาหารและแบ่งงานกันได้แม้คุณไม่อยู่ทั้งวัน',[['เก็บสูตรกับเรื่องเล่าของแต่ละคน',{wisdom:7,bond:8},'สมุดครัวมีลายมือหลายแบบ และมีที่ว่างสำหรับสูตรที่ยังคิดไม่ออก'],['จัดมื้อรวมญาติและเพื่อนบ้าน',{gold:-14,joy:7,bond:8},'โต๊ะยาวไปถึงหน้าประตู คนที่เพิ่งย้ายมาก็มีที่นั่ง'],['เก็บวันธรรมดาไว้ใช้ด้วยกัน',{health:6,joy:8},'คุณไม่ได้เพิ่มงานใหม่ในตาราง เพียงมีเวลานั่งดูคนในบ้านใช้ชีวิตของตน']]]]
 };
 for(const p of H.paths)arcs[p.id].forEach(([title,text,choices],step)=>add('path-'+p.id+'-'+step,title,text,(p.id==='mage'||p.id==='healer'?18:16)+step*8,choices.map(x=>C(...x)),{max:85,humanPathOnly:p.id,humanStep:step,scene:p.scene}));
})();

/* life-legacy.js */
'use strict';
// A small lifetime ledger survives the rolling diary. It records acts, never invents achievements.
const LifeLegacy=(()=>{
 const text=(s,n=380)=>String(s||'').replace(/\s+/g,' ').trim().slice(0,n),kinds=['birth','work','family','journey','decision','project','relationship','loss'];
 function classify(e){const key=e.key||'';if(key.startsWith('society-role-'))return {kind:'decision',weight:80};if(key.startsWith('decision-hazard-'))return {kind:'decision',weight:84};if(key.startsWith('decision-faith-'))return {kind:'project',weight:key.endsWith('-2')?93:80};if(key==='birth')return {kind:'birth',weight:100};if(key==='life-end')return {kind:'loss',weight:95};if(key==='human-family-support')return {kind:'family',weight:76};if(key.startsWith('human-path-')||key==='decision-human-road')return {kind:'decision',weight:70};if(key.startsWith('decision-project-')&&/-2$/.test(key))return {kind:'project',weight:90};if(e.kind==='project-ending')return {kind:'project',weight:90};if(key.startsWith('bond-dream-')&&/-2$/.test(key))return {kind:'relationship',weight:86};if(key.startsWith('bond-promise-'))return {kind:'relationship',weight:80};if(key.startsWith('travel-'))return {kind:'journey',weight:68};if(key.startsWith('career-')||e.title==='งานแรกในเส้นทางชีวิต')return {kind:'work',weight:75};if(key==='decision-love'||key==='decision-family'||/child|partner/.test(key)&&e.kind==='family')return {kind:'family',weight:88};if(key.startsWith('decision-human-path-'))return {kind:'decision',weight:85};if(e.kind==='loss')return {kind:'loss',weight:64};if(e.kind==='decision')return {kind:'decision',weight:48};return null}
 function ensure(s){if(s.lifeLegacy)return s.lifeLegacy;const l=s.lifeLegacy={version:1,entries:[],kingdoms:[s.homeKingdom??s.kingdom],careers:[],decisions:s.turn||0,firstAge:s.age||0,migrated:!!(s.age||s.turn),finalized:false};for(const e of [...(s.diary?.entries||[])].reverse())observe(s,e);if(s.job!==null&&!l.careers.includes(s.job))l.careers.push(s.job);for(const k of s.route||[])if(!l.kingdoms.includes(k))l.kingdoms.push(k);return l}
 function observe(s,e){const l=s.lifeLegacy||ensure(s);if(l.finalized)return;l.decisions=s.turn||0;if(!l.kingdoms.includes(s.kingdom)&&l.kingdoms.length<KINGDOMS.length)l.kingdoms.push(s.kingdom);if(s.job!==null&&!l.careers.includes(s.job)&&l.careers.length<40)l.careers.push(s.job);const c=classify(e);if(!c)return;const key=text(e.key||'entry-'+e.id,160);if(l.entries.some(x=>x.key===key))return;l.entries.push({key,title:text(e.title,290),summary:text(c.kind==='work'&&s.job!==null?'เริ่มทำงานเป็น'+JOBS[s.job][0]+' ใน'+KINGDOMS[s.kingdom][0]:e.paragraphs?.[0]||''),choice:text(e.choice,180),age:e.age??s.age,month:e.month||1,realm:Number.isInteger(e.realm)?e.realm:s.kingdom,kind:c.kind,weight:c.weight});if(l.entries.length>64){let drop=-1;for(let i=0;i<l.entries.length;i++)if(l.entries[i].kind!=='birth'&&l.entries[i].key!=='life-end'&&(drop<0||l.entries[i].weight<l.entries[drop].weight))drop=i;if(drop>=0)l.entries.splice(drop,1);else l.entries.shift()}}
 function seal(s){const l=ensure(s);if(l.finalized||!s.dead)return;l.decisions=s.turn;l.finalized=true;l.age=s.age;l.cause=text(s.cause,500)}
 function summary(s){const l=s.lifeLegacy,source=l?.entries||[],picked=source.filter(e=>!e.legacyEcologyMismatch&&e.kind!=='birth'&&e.kind!=='loss').map((e,index)=>({e,index})).sort((a,b)=>b.e.weight-a.e.weight||a.index-b.index).slice(0,5).map(x=>x.e).sort((a,b)=>a.age-b.age||a.month-b.month),careers=l?.careers?.length?l.careers:s.job!==null?[s.job]:[],worlds=l?.kingdoms?.length?l.kingdoms:[...new Set([s.homeKingdom??s.kingdom,...(s.route||[])])],people=typeof LifeBonds==='undefined'?[]:LifeBonds.memorial(s),departed=(s.bonds?.memorials||[]).slice(0,3),h=s.humanOrigin,clan=h&&!h.migrated&&typeof HumanOrigins!=='undefined'?HumanOrigins.clan(h.clanId):null;
  if(!people.length)for(const m of (s.household?.members||[]).filter(m=>m.alive).slice(0,3))people.push({name:m.name,role:m.role,race:m.race,text:m.role.split(' · ')[0]+' · คนในบ้านของคุณที่ '+KINGDOMS[s.homeKingdom??s.kingdom][0]});
  const title=s.job!==null?JOBS[s.job][0]:careers.length?JOBS[careers.at(-1)][0]:Engine.biological(s)<4?'ชีวิตเล็ก ๆ ในอ้อมแขนของบ้าน':Engine.biological(s)<18?'ช่วงเวลาที่เติบโตกับคนใกล้ตัว':'ชีวิตที่เลือกเดินด้วยตนเอง',origin=KINGDOMS[s.homeKingdom??s.kingdom][0],description='เกิดที่'+origin+(clan?' ในสกุล'+clan.name:'')+' คุณใช้ชีวิต '+s.age+' ปี'+(careers.length?' ผ่านงาน '+careers.length+' อาชีพ':'')+(worlds.length>1?' และเคยเรียก '+worlds.length+' อาณาจักรว่าบ้าน':'')+(s.turn?' เรื่องที่คุณเลือกยังอยู่ในบันทึกเหล่านี้':' ช่วงเวลาของคุณยังอยู่ในบันทึกของบ้านหลังนี้');return {title,description,origin,clan,people:people.slice(0,3),departed,careers,worlds,milestones:picked,migrated:!!l?.migrated,decisions:s.turn,projects:(s.projects?.completed||[]).length,ending:s.ending||'บันทึกหนึ่งชีวิต'};
 }
 function valid(s){const l=s.lifeLegacy;if(l===undefined)return true;const num=(n,a,b)=>Number.isFinite(n)&&n>=a&&n<=b,int=(n,a,b)=>Number.isInteger(n)&&num(n,a,b),str=(x,n)=>typeof x==='string'&&x.length<=n;return l&&l.version===1&&Array.isArray(l.entries)&&l.entries.length<=64&&new Set(l.entries.map(e=>e?.key)).size===l.entries.length&&l.entries.every(e=>e&&str(e.key,160)&&str(e.title,290)&&str(e.summary,380)&&str(e.choice,180)&&num(e.age,0,s.age)&&int(e.month,1,12)&&int(e.realm,0,KINGDOMS.length-1)&&kinds.includes(e.kind)&&int(e.weight,0,100))&&Array.isArray(l.kingdoms)&&l.kingdoms.length<=KINGDOMS.length&&new Set(l.kingdoms).size===l.kingdoms.length&&l.kingdoms.every(k=>int(k,0,KINGDOMS.length-1))&&Array.isArray(l.careers)&&l.careers.length<=40&&new Set(l.careers).size===l.careers.length&&l.careers.every(j=>int(j,0,JOBS.length-1))&&int(l.decisions,0,20000)&&num(l.firstAge,0,s.age)&&typeof l.migrated==='boolean'&&typeof l.finalized==='boolean'&&(!l.finalized||s.dead&&num(l.age,0,s.age)&&str(l.cause,500))}
 return {ensure,observe,seal,summary,valid};
})();

/* human-controls.js */
'use strict';
const HumanUI=(()=>{
 const crest=house=>{const i=HumanOrigins.clans.findIndex(c=>c.id===house.id),colors=['#8a6f48','#6a7b69','#747487','#8c665f','#5c7f85'],c=colors[Math.max(0,i)%colors.length];return `<svg class="house-crest" viewBox="0 0 40 48" aria-hidden="true" shape-rendering="crispEdges"><path d="M4 3h32v27l-4 7-12 9-12-9-4-7Z" fill="${c}"/><path d="M8 7h24v21l-4 6-8 6-8-6-4-6Z" fill="none" stroke="#d8c794" stroke-width="2"/>${i%4===0?'<path d="M18 12h4v20h-4zM11 18h18v4H11z"':i%4===1?'<path d="M20 12l9 17H11z"':i%4===2?'<path d="M11 15h18v5H11zM11 25h18v5H11z"':'<path d="M17 12h6v6h6v6h-6v6h-6v-6h-6v-6h6z"'} fill="#ebdcae"/></svg>`};
 function birth(s){const h=s.humanOrigin;if(!h)return '';if(h.migrated)return `<section class="human-birth"><h3>บ้านสกุล${esc(s.household?.surname||s.name.split(' ').slice(1).join(' '))}</h3><p>${esc(s.household?.originNote||s.family)}</p><p class="human-fine">วัฒนธรรมในถิ่นที่อาศัย · ${esc(HumanOrigins.culture(h.ethnicityId).name)}</p></section>`;const house=HumanOrigins.clan(h.clanId,s),c=HumanOrigins.culture(h.ethnicityId),secondary=HumanOrigins.culture(h.secondaryId);return `<section class="human-birth">${typeof DynastyLife!=='undefined'?DynastyLife.panel(s):''}<div class="house-heading">${crest(house)}<div><small>${esc(HumanOrigins.classLabel(s))}</small><h3>สกุล${esc(house.name)}</h3><p>“${esc(house.motto)}”</p></div></div><p>${esc(house.story)}</p><dl class="human-origin-facts"><div><dt>รากวัฒนธรรม</dt><dd>${esc(c.name)}${secondary?' · '+esc(secondary.name):''}</dd></div><div><dt>ภาษาที่ได้ยินในบ้าน</dt><dd>${esc(c.language)}${secondary?' และ '+esc(secondary.language):''}</dd></div><div><dt>สิ่งที่บ้านส่งต่อ</dt><dd>${esc(house.assets)}</dd></div><div><dt>สิ่งที่อาจต้องรับมือ</dt><dd>${esc(house.burden)}</dd></div></dl><p class="human-fine">ถิ่นเดิมของสกุลอยู่ที่ ${esc(KINGDOMS[house.realm][0])}${house.realm!==s.kingdom?' · คุณเกิดในสาขาที่ '+esc(KINGDOMS[s.kingdom][0]):''} · เส้นทางชีวิตยังเป็นสิ่งที่คุณเลือกเองได้</p></section>`}
 function panel(s){const h=s.humanOrigin;if(!h)return '';const c=HumanOrigins.clan(h.clanId,s),p=HumanOrigins.path(h.path);return `<section class="panel human-path-strip"><div><small>${esc(HumanOrigins.culture(h.ethnicityId).name)} · ${h.migrated?'บ้านสกุล'+esc(s.household?.surname||''):'สกุล'+esc(c.name)}</small><strong>${p?'เส้นทาง · '+esc(p.name):'ชีวิตนี้ยังมีทางให้เลือก'}</strong></div><button class="secondary" data-human-open>${p?'ดูเส้นทาง / ตระกูล':'เลือกเส้นทางชีวิต'} →</button></section>`}
 function open(){const s=state,h=s.humanOrigin;if(!h)return;const house=HumanOrigins.clan(h.clanId,s),locked=s.dead||!s.accepted||s.calendar?.pending||s.outcome||Engine.biological(s)<12;modal(`<section class="human-dialog"><span class="eyebrow">ชาติพันธุ์ · ตระกูล · ชีวิตที่คุณเลือก</span><h2>คุณจะใช้ชีวิตแบบไหน?</h2><p class="human-fine">เส้นทางทำให้เรื่องที่พบและสิ่งที่ฝึกต่างกัน อาชีพเลือกเปลี่ยนได้จากเมนูงาน</p>${locked?'<p class="human-lock">'+(s.dead?'เรื่องของชีวิตนี้ถูกเก็บไว้แล้ว':Engine.biological(s)<12?'ตอนนี้ยังเป็นวัยเติบโต อ่านเส้นทางไว้ก่อนได้':'ตอบเหตุการณ์ที่ค้างอยู่ก่อนเปลี่ยนเส้นทาง')+'</p>':''}<div class="human-path-options">${HumanOrigins.paths.map(p=>`<button data-human-path="${p.id}" aria-pressed="${h.path===p.id}" ${locked||h.path===p.id?'disabled':''}><b>${esc(p.name)}${h.path===p.id?' · กำลังใช้ชีวิตเส้นทางนี้':''}</b><span>${esc(p.description)}</span><small>${h.progress[p.id]?'ผ่านจุดเปลี่ยน '+h.progress[p.id]+'/3':'มีเรื่องต่อเนื่องเฉพาะเส้นทาง'}</small></button>`).join('')}</div><div class="human-path-links"><button class="secondary" id="humanCareers">ดูอาชีพในเส้นทางนี้ →</button><button class="secondary" id="humanHouses">รู้จัก ${HumanOrigins.clans.length} ตระกูล →</button></div><details class="human-family-detail"><summary>บ้านสกุล${esc(h.migrated?s.household?.surname||'':house.name)}${h.migrated?'':' · ความไว้ใจ '+Math.round(h.favor)+'/100'}</summary>${birth(s)}${h.migrated?'':`<p class="human-fine">อิทธิพลเครือข่าย ${house.influence}/100 · ความไว้ใจของบ้านเปลี่ยนตามการตัดสินใจ</p>`}${!h.migrated&&house.gift>0?`<button class="secondary" id="humanGrant" ${HumanOrigins.canSupport(s)?'':'disabled'}>ขอทุนเริ่มต้น ${HumanOrigins.supportAmount(s)} ทอง · ความไว้ใจ −12</button><p class="human-fine">ขอได้ครั้งเดียวในชีวิตเมื่อโตพอและบ้านยังไว้ใจคุณ</p>`:''}</details></section>`);
  document.querySelectorAll('[data-human-path]').forEach(b=>b.onclick=()=>{if(HumanOrigins.choosePath(s,b.dataset.humanPath)){save();clock.reset();render();open();toast('บันทึกเส้นทางที่คุณอยากลองแล้ว')}});$('#humanHouses').onclick=()=>{modal(catalog(s));bindCatalog($('#modalBody'))};$('#humanCareers').onclick=()=>careers(h.path);if($('#humanGrant'))$('#humanGrant').onclick=()=>{if(HumanOrigins.support(s)){save();clock.reset();render();open();toast('ได้รับทุนจากบ้านแล้ว')}};
 }
 function catalog(s){const known=HumanOrigins.clans.filter(c=>WorldHistory.founding(c)<=WorldTimeline.year(s));return `<section class="human-clan-catalog"><span class="eyebrow">บ้านใหญ่และบ้านเล็กของผู้คน</span><h2>${known.length} ตระกูลที่มีบันทึกในยุคนี้</h2><p class="human-fine">อำนาจของตระกูลกับเงินส่วนตัวเป็นคนละส่วน สมาชิกแต่ละคนยังเลือกชีวิตที่ต่างจากบ้านได้</p><label class="world-search"><input id="clanSearch" type="search" placeholder="ค้นหาตระกูล ประเภท หรืออาณาจักร" aria-label="ค้นหาตระกูล"><span id="clanFound">${known.length} ตระกูล</span></label><div class="clan-cards">${known.map(c=>WorldHistory.house(c,WorldTimeline.year(s))).map(c=>`<article data-clan-card class="clan-card ${!s?.humanOrigin?.migrated&&s?.humanOrigin?.clanId===c.id?'is-mine':''}"><div class="house-heading">${crest(c)}<div><small>${esc(HumanOrigins.types.find(t=>t.id===c.type).label)}</small>${TierUI.badge(LifeTiers.humanTypes[c.type],'กำเนิด')}<h3>${esc(c.name)}</h3><p>${esc(KINGDOMS[c.realm][0])}</p></div></div><p>${esc(c.story)}</p><small>“${esc(c.motto)}” · อิทธิพล ${c.influence}/100</small><p class="human-fine">${esc(c.burden)}</p></article>`).join('')}</div></section>`}
 function bindCatalog(root=document){const input=root.querySelector('#clanSearch');if(input)input.oninput=()=>{let count=0;const q=input.value.trim();root.querySelectorAll('[data-clan-card]').forEach(c=>{c.hidden=!c.textContent.includes(q);if(!c.hidden)count++});root.querySelector('#clanFound').textContent=count+' ตระกูล'}}
 function bind(root=document){root.querySelectorAll('[data-human-open]').forEach(b=>b.onclick=open);bindCatalog(root)}
 return {birth,panel,open,catalog,bind,bindCatalog,crest};
})();

/* legacy-controls.js */
'use strict';
const LegacyUI=(()=>{
 let activeLife=null;
 const brief=(s,n=140)=>StoryPresentation.short(s,n);
 function photo(s){const entries=s.diary?.entries||[],candidates=entries.filter(e=>VisualMemory.has(e)&&!e.legacyEcologyMismatch&&!e.legacyAgeMismatch&&!e.visual.dead);return [...candidates].reverse().find(e=>e.visual.age>0&&Engine.ageEquivalent(e.visual.age,e.visual.race)>=18&&['decision','project','relationship','family'].includes(e.kind))||candidates[0]||null}
 function markup(s,{archiveView=false}={}){GameLanguage.register(s);const r=LifeLegacy.summary(s),image=photo(s);return `<section class="legacy-card" aria-label="การ์ดบันทึกชีวิตของ ${esc(s.name)}"><div class="legacy-corners" aria-hidden="true"></div><div class="legacy-heading"><span>บันทึกแห่งชีวิต</span><small>NO. ${s.seed.toString(16).toUpperCase()}</small></div><figure class="legacy-scene"><canvas width="480" height="180" data-legacy-scene role="img" aria-label="ฉากความทรงจำในชีวิตนี้"></canvas><figcaption>${image?'ภาพจากบันทึกเมื่ออายุ '+image.age+' ปี · '+esc(image.title):'บ้านสุดท้าย · '+esc(KINGDOMS[s.kingdom][0])}</figcaption></figure><div class="legacy-name"><small>${esc(RACES[s.race][0])}${s.humanOrigin?' · '+esc(HumanOrigins.culture(s.humanOrigin.ethnicityId).name):''}</small><h2>${esc(s.name)}</h2><p>${esc(r.title)}</p></div><p class="legacy-intro">${esc(r.description)}</p><div class="legacy-measures"><div><b>${s.age}</b><span>ปีที่ได้ใช้ชีวิต</span></div><div><b>${s.turn}</b><span>ครั้งที่ได้เลือก</span></div><div><b>${r.worlds.length}</b><span>อาณาจักรที่เคยอยู่</span></div></div>${r.milestones.length?`<section class="legacy-chapters"><h3>หน้าที่ทำให้ชีวิตนี้เป็นของคุณ</h3><ol>${r.milestones.map(e=>`<li><span>${e.age}<small>ปี</small></span><div><b>${esc(e.title)}</b><p>${esc(brief(e.choice?'คุณเลือก'+e.choice:e.summary,130))}</p></div></li>`).join('')}</ol></section>`:''}${r.people.length?`<section class="legacy-people"><h3>เรื่องของคุณยังอยู่กับพวกเขา</h3>${r.people.map(p=>`<article><b>${esc(p.name)}</b><p>${esc(brief(p.text,160))}</p></article>`).join('')}</section>`:r.departed.length?`<section class="legacy-people"><h3>คนที่เคยเดินทางมาด้วยกัน</h3>${r.departed.map(p=>`<article><b>${esc(p.name)}</b><p>${esc(brief(p.text,160))}</p></article>`).join('')}</section>`:''}<div class="legacy-last"><span aria-hidden="true">· ✦ ·</span><p>${esc(s.cause)}</p><small>${r.migrated?'เรียบเรียงจากบันทึกที่ยังเก็บไว้ · ':''}ชีวิตนี้ถูกเก็บในหอจดหมายเหตุของคุณแล้ว</small></div><div class="legacy-actions"><button class="primary" data-life-reel>ย้อนดูชีวิตนี้ · สไลด์โชว์ →</button><button class="primary" data-legacy-export>เก็บการ์ดชีวิตนี้เป็นภาพ ↓</button>${archiveView?'<button class="secondary" data-legacy-log>อ่านบันทึกเหตุการณ์ทั้งหมด →</button>':`<button class="secondary" id="share">แบ่งปันเรื่องของชีวิตนี้</button><button class="legacy-next" id="reborn">เมื่อพร้อมแล้ว · เริ่มชีวิตใหม่ →</button>`}</div><p class="legacy-export-status" role="status" aria-live="polite"></p></section>`}
 function paint(root,s){root.querySelectorAll('[data-legacy-scene]').forEach(canvas=>{const e=photo(s);if(e)Illustration.drawScene(canvas,VisualMemory.read(s,e),0);else Illustration.drawScene(canvas,{...s,sceneOverride:(s.race?Ecology.profile(s).scene:'garden')+'-realm-'+s.kingdom,sceneOnly:false},0)})}
 function wrap(ctx,value,x,y,width,font,lineHeight,maxLines=10){value=GameLanguage.text(value);ctx.font=font;let line='',lines=[];const parts=typeof Intl.Segmenter==='function'?[...new Intl.Segmenter(GameLanguage.locale,{granularity:'word'}).segment(String(value))].map(x=>x.segment):Array.from(String(value));for(const part of parts){if(ctx.measureText(line+part).width>width&&line){lines.push(line);line=part}else line+=part}if(line)lines.push(line);if(lines.length>maxLines){lines=lines.slice(0,maxLines);lines[maxLines-1]=lines[maxLines-1].slice(0,-2)+'…'}for(const line of lines){ctx.fillText(line,x,y);y+=lineHeight}return y}
 async function cardImage(s){GameLanguage.register(s);await document.fonts.ready;const r=LifeLegacy.summary(s),canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1740;const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;c.fillStyle='#f3f0e5';c.fillRect(0,0,1080,1740);c.strokeStyle='#8c987e';c.lineWidth=3;c.strokeRect(34,34,1012,1672);c.lineWidth=1;c.strokeRect(44,44,992,1652);for(const [x,y]of [[32,32],[1026,32],[32,1686],[1026,1686]]){c.fillStyle='#8f805f';c.fillRect(x,y,22,4);c.fillRect(x,y,4,22)}c.fillStyle='#6e7b62';c.font='22px "IBM Plex Sans Thai", sans-serif';c.fillText('1 in 10 Billion · FANTASY',72,96);c.textAlign='right';c.fillText(s.seed.toString(16).toUpperCase(),1008,96);c.textAlign='left';const shot=document.createElement('canvas');shot.width=480;shot.height=180;const e=photo(s);Illustration.drawScene(shot,e?VisualMemory.read(s,e):{...s,sceneOverride:(s.race?Ecology.profile(s).scene:'garden')+'-realm-'+s.kingdom},0);c.drawImage(shot,72,128,936,351);c.fillStyle='#63705d';c.font='19px "IBM Plex Sans Thai", sans-serif';c.fillText(e?'อายุ '+e.age+' ปี · '+brief(e.title,55):'บันทึกสุดท้ายจาก '+KINGDOMS[s.kingdom][0],72,512);c.fillStyle='#334339';let y=wrap(c,s.name,72,588,936,'bold 43px "IBM Plex Sans Thai", sans-serif',60,2);c.fillStyle='#7d7a66';y=wrap(c,r.title+' · '+RACES[s.race][0],72,y+14,936,'25px "IBM Plex Sans Thai", sans-serif',38,2);c.fillStyle='#465a4a';c.font='bold 37px "IBM Plex Sans Thai", sans-serif';c.fillText(s.age+' ปี',72,y+70);c.fillText(s.turn+' การตัดสินใจ',345,y+70);c.fillText(r.worlds.length+' อาณาจักร',735,y+70);y+=116;c.strokeStyle='#c6cdbb';c.beginPath();c.moveTo(72,y);c.lineTo(1008,y);c.stroke();y+=45;c.fillStyle='#405341';y=wrap(c,'หน้าที่ทำให้ชีวิตนี้เป็นของคุณ',72,y,936,'bold 25px "IBM Plex Sans Thai", sans-serif',38,1);for(const m of r.milestones.slice(0,3)){c.fillStyle='#99845a';c.font='23px "IBM Plex Sans Thai", sans-serif';c.fillText(m.age+' ปี',72,y+28);c.fillStyle='#3d4d40';const end=wrap(c,m.title,185,y+28,810,'bold 24px "IBM Plex Sans Thai", sans-serif',34,2);c.fillStyle='#74806c';y=wrap(c,brief(m.choice?'คุณเลือก'+m.choice:m.summary,115),185,end+2,810,'21px "IBM Plex Sans Thai", sans-serif',31,2)+22}const person=r.people[0]||r.departed[0];if(person&&y<1350){c.fillStyle='#6f7e63';y=wrap(c,r.people.length?'เรื่องของคุณยังอยู่กับ '+person.name:'คนที่เคยร่วมทาง · '+person.name,72,y+12,936,'bold 23px "IBM Plex Sans Thai", sans-serif',34,2);c.fillStyle='#69765f';y=wrap(c,brief(person.text,150),72,y+6,936,'22px "IBM Plex Sans Thai", sans-serif',34,3)}c.fillStyle='#937652';c.textAlign='center';c.font='24px Georgia';c.fillText('· ✦ ·',540,1590);c.fillStyle='#6f7869';c.font='20px "IBM Plex Sans Thai", sans-serif';c.fillText(brief(s.cause,78),540,1630);c.font='17px "IBM Plex Sans Thai", sans-serif';c.fillText('หนึ่งชีวิตที่เลือกเอง · '+r.origin,540,1666);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Image unavailable');return blob}
 function bind(root=document,s=state){paint(root,s);LifeReelUI.bind(root,s);root.querySelectorAll('[data-legacy-log]').forEach(b=>b.onclick=()=>modal(`<h2>บันทึกของ ${esc(s.name)}</h2>${s.log.map(l=>`<div class="log"><strong>อายุ ${l.age} ปี</strong>${esc(l.text)}</div>`).join('')}`));root.querySelectorAll('[data-legacy-export]').forEach(b=>b.onclick=async()=>{const status=root.querySelector('.legacy-export-status');b.disabled=true;if(status)status.textContent='กำลังเก็บภาพและเรื่องราวของชีวิตนี้…';try{const blob=await cardImage(s),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='fantasy-life-'+s.seed+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);if(status)status.textContent='เก็บการ์ดชีวิตนี้แล้ว · ไฟล์ PNG'}catch(e){if(status)status.textContent='ยังเก็บภาพไม่ได้ ลองอีกครั้งได้ครับ'}finally{b.disabled=false}})}
 function open(s){activeLife=s;modal(markup(s,{archiveView:true}));bind($('#modalBody'),s)}
 return {markup,paint,bind,open,cardImage};
})();

