/* ecology-days.js */
'use strict';
const EcologyDays={
 tree:[['ทางบนยอดไม้','ใบชุดใหม่บังทางที่เคยใช้ คุณลองทางอ้อมและเหลือช่องให้สัตว์เล็กผ่าน'],['ผลสุกที่ยังไม่เก็บ','ผลบนกิ่งสูงเริ่มสุกพร้อมกัน คุณเว้นกิ่งที่รังเล็กกำลังใช้อยู่'],['คืนที่มองเห็นดาว','ช่องใบไม้เปิดให้เห็นดาวดวงที่เคยหาไม่พบ คุณอยู่ดูจนมันพ้นแนวเรือนยอด'],['เสียงใต้เปลือกไม้','เสียงจากต้นเดิมเบาลง คุณแจ้งผู้ดูแลรากก่อนใช้ชานร่วมกันอีกครั้ง']],
 cave:[['หินที่เก็บเสียง','เสียงเรียกสะท้อนกลับมาสั้นลง คุณหยุดที่ช่องกว้างและรอจนแยกทางลมได้'],['แสงแร่ครั้งแรกของฤดู','แร่ตามผนังเริ่มเรืองแสง กลุ่มปิดไฟส่วนเกินเพื่อให้ร่างปรับตัวทีละน้อย'],['ทางผ่านของตัวเล็ก','คุณพบรอยสมาชิกเล็กในช่องแคบ จึงเว้นทางนั้นแทนการขยายให้ตนผ่าน'],['หยดน้ำที่หายไป','แอ่งซึ่งเคยมีน้ำหยดเงียบลง คุณตามเสียงน้ำไปจนพบร่องใหม่หลังหิน']],
 marsh:[['วงน้ำใต้พงอ้อ','ระลอกเล็กวิ่งสวนลม คุณหยุดในน้ำตื้นจนรู้ว่าสัตว์อีกตัวกำลังผ่าน'],['ตลิ่งใหม่หลังฝน','โคลนบนทางขึ้นยังอ่อน คุณลองแรงที่ริมแอ่งก่อนเรียกฝูงไปใช้ทางข้างกัน'],['ที่พักในพงอ้อ','ลมพัดพงอ้อให้มีช่องอุ่นขึ้น คุณเลือกพักตรงที่ยังรับรู้สัญญาณของฝูงได้'],['คืนเสียงกบ','เสียงกบดังขึ้นหลังฝน คุณเงียบฟังจนจำเสียงที่หายไปจากเมื่อคืนได้']],
 river:[['น้ำใสหลังตะกอนผ่าน','แสงแตะพื้นแอ่งอีกครั้ง คุณออกจากแนวพักทีละน้อยเพื่อทดสอบกระแส'],['ทางที่ปลาเล็กใช้','ฝูงปลาอ่อนหลบอยู่ในร่องน้ำ คุณเว้นช่องนั้นและเลี่ยงส่วนที่ตื้นกว่า'],['เสียงจากเหนือน้ำ','เงาบนผิวน้ำบดแสงชั่วครู่ คุณรอใต้หินจนสัญญาณรบกวนผ่านไป'],['ก้อนหินที่จำได้','น้ำพัดทรายออกจากหินลายเก่า คุณรู้ว่าทางกลับยังอยู่แม้มันดูต่างไป']],
 reef:[['ช่วงปะการังปล่อยชีวิตใหม่','น้ำมีจุดเล็กเต็มไปหมด คุณลดการเคลื่อนผ่านแนวอ่อนและพักด้านรับกระแส'],['ผู้มาอาศัยในโพรง','สัตว์ตัวเล็กเข้าพักในโพรงข้างคุณ คุณขยับแนวผ่านให้มันไม่ต้องหนีทุกครั้ง'],['เงาหลังแนวปะการัง','เงาใหญ่เคลื่อนเหนือแนวพัก คุณนิ่งอยู่ใต้กิ่งแข็งจนความสั่นในน้ำเบาลง'],['ทรายออกจากกิ่งอ่อน','กระแสพาทรายที่ทับกิ่งหลุดออก คุณกลับไปดูว่าพื้นผิวรับแสงยังฟื้นได้ไหม']],
 ocean:[['จังหวะของฝูงปลา','ฝูงปลาเปลี่ยนแนวพร้อมกัน คุณปรับทางตามช่องที่เปิดแทนการเร่งตามฝูง'],['เสียงซึ่งเดินทางมาไกล','เสียงเรียกจากกลุ่มอื่นมาถึงก่อนเห็นตัว คุณตอบจากระยะที่ไม่รบกวนทางผ่าน'],['กระแสเย็นชั้นล่าง','ชั้นน้ำเย็นเลื่อนสูงขึ้น คุณตามแนวที่ร่างรับไหวและคอยฟังสมาชิกที่ช้ากว่า'],['คืนแสงเล็กในน้ำ','สิ่งมีชีวิตเรืองแสงติดตามทางที่คุณเคลื่อน คุณลดแรงจนเห็นจุดแสงแยกจากกัน']],
 cliff:[['ขนที่ลมพากลับ','ลมหมุนพาวัสดุเก่าของรังกลับมา คุณแยกส่วนที่ยังอ่อนจากสิ่งที่บาดร่างได้'],['ร่อนระยะสั้น','แรงยกพอดีสำหรับลองทางสั้น คุณกลับก่อนเมฆจะปิดแนวอ้างอิง'],['รังที่ตอบกลับมา','คุณส่งเสียงสั้นไปอีกฝั่ง เสียงตอบทำให้รู้ว่ากลุ่มข้างเคียงผ่านคืนลมแรงมาได้'],['เงาริมหน้าผา','สัตว์ใหญ่บินตัดแนวรัง คุณรอใต้ส่วนกำบังจนแนวบินกลับมาปลอดภัย']],
 dune:[['น้ำค้างก่อนรุ่งสาง','รอยเย็นบนหินยังเหลืออยู่ คุณรับความชื้นก่อนแสงจะไล่มันหายไป'],['ทรายซึ่งไม่เหมือนเดิม','ลมกลบรอยทางจนเรียบ คุณใช้แนวหินเดิมหาทางกลับแทนรอยที่หายไป'],['พักเมื่อแดดตรงหัว','ความร้อนเริ่มขวางการรับรู้ คุณเลื่อนการสำรวจออกไปและอยู่ในแนวเงาลึก'],['ผู้ผ่านโอเอซิส','กลุ่มเดินทางรอความร้อนลดอยู่ไกล ๆ คุณส่งสัญญาณขอบเขตที่ต่างฝ่ายพักได้']],
 steppe:[['หญ้าใหม่หลังฝน','แนวเขียวเริ่มขึ้นที่ลาดต่ำ กลุ่มลองผ่านเฉพาะส่วนที่พื้นยังรับน้ำหนักได้'],['สมาชิกที่กลับช้า','คุณรอที่แนวพักจนสัญญาณตัวสุดท้ายมาถึง กลุ่มจึงออกต่อพร้อมกัน'],['กลิ่นจากปลายทุ่ง','กลิ่นผู้ล่ามาตามลม คุณเลี่ยงแนวหญ้าสูงและไม่ส่งเสียงเกินจำเป็น'],['ทางเดิมต่างฤดู','ดอกหญ้ากลบรอยคุ้นเคย คุณจำแนวเนินได้ก่อนจะเห็นจุดพักเดิม']],
 frost:[['ผลึกที่คืนรูป','ความเย็นยามค่ำทำให้พื้นกลับมั่นคง คุณตรวจรอยอ่อนก่อนพักเต็มร่าง'],['ลมที่ต้องหลบ','เสียงลมเปลี่ยนเป็นเสียงสูง คุณย้ายเข้าด้านกำบังและรอโดยไม่ฝืนผ่าน'],['รอยทางบนหิมะใหม่','รอยที่เพิ่งผ่านไปถูกหิมะคลุม คุณเว้นช่วงสำรวจให้พอสังเกตสภาพขากลับ'],['แสงอุ่นที่ริมโพรง','แสงแตะขอบเขตพัก คุณถอยตามแนวเย็นซึ่งยังไม่รบกวนการคงรูป']],
 ember:[['แกนอุ่นซึ่งยังอยู่','เปลวด้านนอกอ่อนลง แต่แกนใต้หินยังให้ความอุ่น คุณพักใกล้โดยเว้นที่ให้ผู้อื่น'],['ประกายที่พ้นขอบ','ลมพาประกายออกนอกเขต คุณหยุดการฝึกจนผู้ร่วมถิ่นถอยถึงแนวปลอดภัย'],['เถ้าของรังเก่า','เถ้าชั้นบนเผยรอยพักเดิม คุณเว้นส่วนหนึ่งไว้ให้กลุ่มจดจำทางกลับ'],['ลมเย็นหลังผา','ด้านหนึ่งของรังเย็นเร็วกว่าที่เคย คุณบอกกลุ่มก่อนแบ่งจุดพักใหม่']],
 spirit:[['เสียงที่ยืนยันตัวตน','เสียงเรียกจากจุดยึดคุ้นเคยยังอยู่ คุณตอบจนขอบร่างกลับมาชัดขึ้น'],['แสงที่ทับกัน','แสงจากผู้มาเยือนทำให้เงารวมกัน คุณถอยให้มีระยะพอแยกสัญญาณของตน'],['ความทรงจำซึ่งผ่านไป','สัญญาณเก่าผ่านแนวพัก คุณรับรู้มันโดยไม่ดึงทุกภาพมาเป็นเรื่องของตน'],['จุดยึดที่ได้พัก','คุณลดการส่งสัญญาณรอบจุดยึด เหลือความเงียบพอให้สมาชิกที่เพิ่งก่อรูปพัก']],
 stone:[['แรงสั่นในข้อต่อ','เสียงแกนต่างจากครั้งก่อน คุณลดแรงจนรู้ว่าจุดใดต้องพักก่อนใช้อีก'],['แร่ซึ่งเข้ากับร่าง','แร่ชั้นใหม่ตอบรับแกนเบา ๆ คุณทดลองทีละส่วนแทนการเปลี่ยนพร้อมกัน'],['คำสั่งที่เลือกไม่ทำ','แรงจากรอยเดิมเรียกให้ขยับ คุณหยุดฟังเจตนาของตนก่อนตอบรับมัน'],['รอยซ่อมที่ยังเห็น','รอยเดิมยังอยู่หลังพัก คุณลองควบคุมแรงตามสภาพใหม่จนเคลื่อนไหวได้มั่นคง']],
 web:[['แรงสั่นที่จำได้','เส้นใยส่งจังหวะคุ้นเคยมา คุณตอบจากแนวพักก่อนอีกฝ่ายเข้าถึง'],['ช่องว่างให้ตัวเล็ก','ใยอ่อนติดทางผ่าน คุณเว้นช่องให้สมาชิกเล็กออกมาโดยไม่กระตุกเส้นหลัก'],['หยดฝนบนใย','หยดน้ำเปลี่ยนแรงตึง คุณตรวจแนวที่รับมากที่สุดก่อนออกจากชาน'],['ใยเก่าซึ่งส่งต่อ','เส้นที่เคยใช้เริ่มอ่อน คุณทำเครื่องหมายด้วยแรงสั่นให้กลุ่มเลี่ยงก่อนรับช่วงใหม่']],
 root:[['รสใหม่ในน้ำฝน','ความชื้นมาถึงพร้อมแร่ที่ต่างไป คุณรับทีละน้อยก่อนขยายแนวราก'],['หน่อข้างราก','ส่วนอ่อนเริ่มก่อรูปใกล้แนวพัก คุณเว้นแสงและแหล่งอาหารให้มันตั้งตัว'],['ดินที่ได้หายใจ','น้ำลดจากโพรงเล็ก กลุ่มค่อย ๆ คืนช่องอากาศให้รากแทนการเปิดพร้อมกัน'],['สัญญาณใต้ดิน','แรงเบาจากอีกแนวรากมาถึง คุณส่งกลับจนรู้ว่ายังเชื่อมถึงกันได้']],
 glade:[['น้ำค้างบนมอส','คุณออกสำรวจขณะมอสยังชื้น ก่อนกลับเมื่อแดดทำให้พื้นผิวเริ่มแห้ง'],['ดอกที่บานช้ากว่า','ดอกข้างเขตพักเพิ่งเปิด คุณเว้นมันไว้ให้สัตว์เล็กซึ่งมาถึงทีหลัง'],['เงาที่ผ่านลาน','เงาจากเหนือพุ่มกวาดผ่าน คุณรอใต้แนวกำบังจนสัญญาณของถิ่นกลับมา'],['มุมพักใต้ใบกว้าง','ฝนยังตกแต่ใต้ใบกว้างสงบ คุณอยู่ฟังจังหวะฝนจนร่างพร้อมออกไปอีกครั้ง']]
};

