/* economy.js */
'use strict';
const Economy=(()=>{
 const round=n=>Math.round(n*100)/100,cap=(n,a=0,b=1e9)=>Math.max(a,Math.min(b,n)),hash=(s,k)=>{let n=Math.imul((s.seed^k)>>>0,2654435761);return (n^(n>>>16))>>>0};
 const regions=[1.05,1.08,.94,.93,1.24,1.18,1.1,.78,1.06,.9,1.3,.82,1.22,.87,.8,1.17];
 const annualPay=j=>{const name=j[0];if(/ฝึกหัด|ผู้ช่วย|ลูกมือ|เริ่มฝึก/.test(name))return 32000;if(/จอมมาร|ราชัน|จักรพรรดิ|ผู้ปกครอง/.test(name))return 180000;if(/จอมเวท|ศัลย|แพทย์|นักวิจัย|วิศว|ผู้บัญชา/.test(name))return 105000;if(/นักเวท|ผู้ร่าย|นักกฎหมาย|ผู้พิพากษา/.test(name))return 82000;if(/อัศวิน|นักบัญชี|เจ้าหน้าที่|ช่างกล|นักการทูต/.test(name))return 62000;if(/ผจญภัย|นักล่า|นักสำรวจ|โจรสลัด/.test(name))return 52000;if(/ชาวนา|ชาวไร่|รับจ้าง|คนงาน|ผู้ช่วย|กอบลิน/.test(name))return 32000;if(/ดนตรี|นักแสดง|นักเต้น|กวี|ศิลปิน/.test(name))return 38000;return cap(j[3]*4000,34000,88000)};
 const wages=[],actions=[{id:'shift',name:'รับงานเพิ่มหนึ่งช่วง',description:'ได้ค่าจ้างสุทธิ 360–720 ทอง · สุขภาพ −3 ความสุข −2',min:16},{id:'aid',name:'ขอทุนฉุกเฉินจากชุมชน',description:'เฉพาะเงินพร้อมใช้น้อยกว่า 1,000 และมีหนี้ · ไม่เกินปีละครั้ง',min:16},{id:'family',name:'ช่วยเงินครอบครัว 500 ทอง',description:'โอนจริงจากเงินส่วนตัวเข้าเงินครอบครัว',min:16},{id:'repay',name:'ชำระหนี้ 500 ทอง',description:'ลดเงินต้นที่ต้องจ่ายดอกเบี้ย',min:16}];
 function initialize(s,migrated){return s.economy={version:1,migrated,lastQuarter:-1,lastYear:s.age,budget:'standard',housing:'family',debt:0,missed:0,actionQuarter:-1,aidYear:-1,familyFund:[300,1200,4500,15000,45000,120000,450000,2000000][s.rank],familyArrears:0,last:null,history:[]}}
 function ensure(s){return s.economy||initialize(s,true)}
 function birth(s){initialize(s,false);s.gold=0;if(s.race!==0&&typeof SpeciesSociety!=='undefined'){const funds=SpeciesSociety.finance(s);s.economy.familyFund=funds.fund}if(typeof RaceDrives!=='undefined'&&RaceDrives.cashless(s))s.economy.familyFund=0;accounts(s)}
 function migrate(s){if(s.economy){if(!s.economy.accounts){if(s.age===0&&s.turn===0&&(s.calendar?.count??0)<=1&&s.gold>0){s.economy.familyFund=round(cap(s.economy.familyFund+s.gold));s.gold=0}accounts(s)}return;}const mul=n=>round(cap(n*100));s.gold=mul(s.gold);if(s.spending){s.spending.lastBio=s.age+(s.calendar?.quarter||0)/4;s.spending.portfolio.year=Math.floor(s.age);s.spending.portfolio.balance=mul(s.spending.portfolio.balance);s.spending.portfolio.earned=round(cap(s.spending.portfolio.earned*100,-1e9,1e9))}if(s.livelihood){s.livelihood.lastIncome=mul(s.livelihood.lastIncome||0);s.livelihood.lastHouseholdCost=mul(s.livelihood.lastHouseholdCost||0);const b=s.livelihood.business;if(b)for(const key of ['cash','debt','lastRevenue','lastCosts','lastProfit','totalProfit','ownerDraw'])b[key]=round(cap(b[key]*100,-1e7,1e7))}initialize(s,true)}
 function tax(annual){return round(Math.max(0,annual)*.0765+Math.max(0,Math.min(annual-15000,45000))*.12+Math.max(0,annual-60000)*.22)}
 function salary(s){return s.job===null||RaceDrives.cashless(s)||(typeof Adventures!=='undefined'&&Adventures.isCareer(s))?0:round((wages[s.job]||34000)*(typeof RealmLife==='undefined'?1:RealmLife.wageFactor(s))*(1+Livelihood.ensure(s).level*.12)*(s.livelihood?.workload??1)*(s.livelihood?.tenure<1?.88:1))}
 function quote(s){const e=ensure(s),region=regions[s.kingdom],world=WorldTimeline.impact(s),native=Ecology.native(s),owned=!!s.spending?.home.owned,scale=e.budget==='lean'?.82:e.budget==='comfort'?1.4:1;const categories=s.race!==0?SpeciesSociety.living(s,e,owned,{housing:owned?650:e.housing==='family'?750:1650,food:520,utilities:e.housing==='family'?150:270,health:480,transport:380,needs:260}):{housing:owned?650:e.housing==='family'?750:1650,food:520,utilities:e.housing==='family'?150:270,health:480,transport:380,needs:260};if(e.housing==='guild'&&typeof Adventures!=='undefined'&&Adventures.ensure(s).member&&!owned&&!s.children&&!RaceDrives.cashless(s)){categories.housing=[27,46,53].includes(s.race)?625:250;categories.food*=.78;categories.utilities*=.7;categories.transport*=.5}if(s.children)categories.needs+=s.children*300;if(typeof Adventures!=='undefined'&&Adventures.isCareer(s))categories.expedition=40+Adventures.ensure(s).rank*100;if(owned&&typeof Housing!=='undefined')categories.housing=Housing.upkeep(s)/12;const rows=Object.entries(categories).map(([id,value])=>({id,monthly:round((RaceDrives.cashless(s)?0:value)*region*(id==='food'||id==='transport'?world.price:1)*(id==='housing'&&owned?1:scale))}));return {rows,monthly:round(rows.reduce((n,r)=>n+r.monthly,0)),region,world,native,scale}}
 function add(s,title,text,extra={}){const e=ensure(s);e.history.unshift({age:s.age,title,text});e.history.length=Math.min(24,e.history.length);return Narrative.append(s,{title,paragraphs:[text],kind:'finance',key:'economy-'+s.calendar.count+'-'+title,scene:Ecology.profile(s).scene,ecology:true,...extra})}
 function accounts(s){const e=ensure(s),y=WorldTimeline.year(s);if(!e.accounts)e.accounts={version:1,year:y,current:blank(),closed:[],giftYear:-1};const a=e.accounts;if(a.year!==y){s.seen=s.seen.filter(id=>id!=='family-pocket-gift'&&id!=='household-endowment');a.closed.unshift({year:a.year,...a.current});a.closed=a.closed.slice(0,12);a.year=y;a.current=blank()}return a}
 function blank(){return {gross:0,tax:0,support:0,expenses:0,interest:0,principal:0,shortfall:0,otherIncome:0,otherSpend:0}}
 function record(s,key,amount){if(!Number.isFinite(amount)||amount<0||!Object.hasOwn(blank(),key))return;const a=accounts(s);a.current[key]=round(cap(a.current[key]+amount))}
 function annual(s){const a=accounts(s),x=a.current;return {year:a.year,...x,income:round(x.gross-x.tax+x.support+x.otherIncome),outgo:round(x.expenses+x.otherSpend+x.principal),cost:round(x.expenses+x.otherSpend+x.interest),last:a.closed[0]||null}}
 function quarter(s){const e=ensure(s),q=s.calendar?.count??0;if(s.dead||!s.accepted||e.lastQuarter===q)return;e.lastQuarter=q;accounts(s);const age=Engine.biological(s),quoteNow=quote(s),world=quoteNow.world;const relatives=FamilyWorld.list(s).filter(m=>m.alive),guardians=relatives.filter(m=>!m.id.startsWith('child-')&&m.id!=='partner'&&Engine.ageEquivalent(FamilyWorld.age(s,m),m.race)>=18),supported=guardians.length>0&&age<22;
  if(RaceDrives.cashless(s)){const interest=round(e.debt*.18/4);e.debt=round(cap(e.debt+interest));record(s,'interest',interest);e.last={year:WorldTimeline.year(s),quarter:s.calendar.quarter,gross:0,tax:0,support:0,expenses:0,interest,principal:0,shortfall:0,net:-interest,familyIncome:0,familyExpenses:0,nativeCashless:1};const l=Livelihood.ensure(s);l.lastIncome=0;l.lastHouseholdCost=0;return}
  const familyBase=s.race!==0?SpeciesSociety.finance(s).wage:[34000,41000,58000,82000,100000,145000,250000,720000][s.heritage?.birthRank??s.rank],familyWage=familyBase*(guardians.length?Math.min(1.35,guardians.length/2):0),familyNet=(familyWage-tax(familyWage))/4*world.jobs,children=relatives.filter(m=>Engine.ageEquivalent(FamilyWorld.age(s,m),m.race)<18).length+(age<18?1:0),familyBill=s.race!==0?SpeciesSociety.familyBill(s,children,quoteNow.monthly):((29000+children*4800+[0,0,2500,6000,9000,14000,40000,160000][s.heritage?.birthRank??s.rank])/4)*regions[s.kingdom]*world.price;
  const available=e.familyFund+familyNet;if(available<familyBill){e.familyArrears=round(cap(e.familyArrears+familyBill-available,0,250000));e.familyFund=0}else{e.familyFund=round(cap(available-familyBill));const pay=Math.min(e.familyFund*.08,e.familyArrears);e.familyFund=round(e.familyFund-pay);e.familyArrears=round(e.familyArrears-pay)}
  let gross=0,taxes=0,support=0,expenses=0,interest=0,principal=0,shortfall=0;
  if(age<16){if(e.familyArrears>0){s.joy=cap(s.joy-.35,0,100);if(q%4===0)add(s,'สิ่งที่บ้านต้องเลื่อนไปก่อน',FamilyWorld.primary(s).name+'กันเงินไว้สำหรับของจำเป็นก่อน ค่าเรียนหรือของที่อยากได้ต้องรอไปอีกช่วง',{tone:'loss'})}}
  else{const pay=salary(s),irregular=s.job!==null&&/ดนตรี|ศิลปิน|นักแสดง|พ่อค้า/.test(JOBS[s.job][0]),variance=irregular?.7+(hash(s,q+335)%61)/100:1,disruption=world.severity>.4&&hash(s,q+119)%100<Math.round(world.severity*20);gross=round(pay/4*world.jobs*variance*(disruption?.45:1));if(typeof Adventures!=='undefined'&&Adventures.ensure(s).active&&pay>0)gross=round(gross*.35);taxes=round(tax(gross*4)/4);s.gold=round(cap(s.gold+gross-taxes));
   expenses=round(quoteNow.monthly*3*(age<18?.65:1));if(supported&&e.housing==='family'){support=round(Math.min(e.familyFund*.025,expenses*(s.rank>=6?.5:.15)));e.familyFund=round(e.familyFund-support);s.gold=round(cap(s.gold+support))}
   const emergency=world.severity>.35&&hash(s,q+739)%100<Math.round(5+world.severity*10)?round((500+hash(s,q+919)%2400)*world.price):0;expenses+=emergency;interest=round(e.debt*.18/4);e.debt=round(cap(e.debt+interest));principal=round(Math.min(e.debt,Math.max(0,s.gold-expenses)*.12));s.gold=round(s.gold-principal);e.debt=round(e.debt-principal);const paid=Math.min(s.gold,expenses);s.gold=round(s.gold-paid);shortfall=round(expenses-paid);if(shortfall>0){const line=Math.max(6000,Math.min(80000,salary(s)*.65+(typeof Adventures!=='undefined'&&Adventures.ensure(s).member?18000:0)));const credit=Math.min(shortfall,Math.max(0,line-e.debt));e.debt=round(cap(e.debt+credit));e.missed++;s.joy=cap(s.joy-Math.min(3,.6+e.missed*.15),0,100);s.health=Math.max(Math.min(25,s.health),s.health-(e.budget==='lean'?.2:.4));if(q%4===0||e.missed===1)add(s,'เงินไม่พอถึงวันจ่าย',`รายรับสุทธิ ${round(gross-taxes).toLocaleString('en-US')} ทอง ค่าใช้จ่าย ${expenses.toLocaleString('en-US')} ทอง ส่วนขาด ${shortfall.toLocaleString('en-US')} ทองยังขาด ส่วนที่เกินวงเงินกู้ทำให้บางบริการต้องเลื่อน คุณต้องเลือกระหว่างงานเพิ่ม การรักษา และสิ่งที่รอได้`,{tone:'loss'})}else{e.missed=Math.max(0,e.missed-1);if(e.budget==='comfort')s.joy=cap(s.joy+.4,0,100)}
   if(emergency)add(s,'บิลที่ไม่ได้เตรียมใจ',`ค่ารักษา ซ่อมแซม หรือย้ายแหล่งพักเพิ่ม ${emergency.toLocaleString('en-US')} ทอง`,{tone:'critical'});
  }
  e.last={year:WorldTimeline.year(s),quarter:s.calendar.quarter,gross,tax:taxes,support,expenses,interest,principal,shortfall,net:round(gross-taxes+support-expenses-interest),familyIncome:round(familyNet),familyExpenses:round(familyBill)};for(const k of ['gross','tax','support','expenses','interest','principal','shortfall'])record(s,k,e.last[k]);const l=Livelihood.ensure(s);l.lastIncome=round(gross-taxes);l.lastHouseholdCost=expenses;if(q%4===0&&age>=16&&!shortfall){const y=annual(s);add(s,'สมุดรายรับรายจ่ายปี '+y.year,`รับสุทธิปีนี้ ${y.income.toLocaleString('en-US')} ทอง ภาระและการใช้จ่าย ${y.cost.toLocaleString('en-US')} ทอง เงินพร้อมใช้ ${s.gold.toLocaleString('en-US')} ทอง`)}
 }
 function giver(s){return FamilyWorld.list(s).find(m=>m.alive&&Engine.ageEquivalent(FamilyWorld.age(s,m),m.race)>=18)||null}
 function canGift(s){const e=ensure(s),a=accounts(s);return Engine.biological(s)>=6&&Engine.biological(s)<18&&FamilyWorld.list(s).some(m=>m.alive&&Engine.ageEquivalent(FamilyWorld.age(s,m),m.race)>=18)&&a.giftYear!==a.year&&(RaceDrives.cashless(s)?s.raceDrives.resource>=30:e.familyFund>=300)}
 function giftAmount(s){return RaceDrives.cashless(s)?0:round(Math.min(ensure(s).familyFund*.008,s.race===0?[15,25,50,100,200,350,750,2000][s.heritage?.birthRank??s.rank]:SpeciesSociety.allowance(s)))}
 function receiveGift(s){if(!canGift(s))return false;const e=ensure(s),a=accounts(s),amount=giftAmount(s);a.giftYear=a.year;if(RaceDrives.cashless(s)){s.raceDrives.resource=Math.min(100,s.raceDrives.resource+6);add(s,'ส่วนที่ผู้ดูแลกันไว้ให้',giver(s).name+'แบ่งแหล่งดำรงชีวิตในถิ่นให้คุณเพิ่ม โดยยังเฝ้าดูว่าร่างใช้ได้พอหรือไม่')}else{e.familyFund=round(e.familyFund-amount);s.gold=round(cap(s.gold+amount));record(s,'support',amount);add(s,'เงินที่บ้านมอบให้',giver(s).name+'มอบ '+amount+' ทองให้คุณ เงินนี้มาจากส่วนสำรองของบ้านจริง')}return true}
 function setPlan(s,key,value){const e=ensure(s);if(s.dead||!s.accepted||s.outcome||s.calendar?.pending||Engine.biological(s)<16)return false;if(key==='housing'&&value==='guild'&&(!Adventures.ensure(s).member||s.spending.home.owned||s.children))return false;if(key==='budget'&&!['lean','standard','comfort'].includes(value)||key==='housing'&&!['family','rent','guild'].includes(value)||!['budget','housing'].includes(key)||e[key]===value)return false;e[key]=value;return true}
 function action(s,id){const e=ensure(s),q=s.calendar?.count??0,a=actions.find(a=>a.id===id);if(!a||typeof RaceDrives!=='undefined'&&RaceDrives.cashless(s)&&['shift','aid'].includes(id)||s.dead||!s.accepted||s.outcome||s.calendar?.pending||Engine.biological(s)<a.min||e.actionQuarter===q)return false;let text='';if(id==='shift'){const value=360+hash(s,q+721)%361;s.gold=round(cap(s.gold+value));s.health=cap(s.health-3,0,100);s.joy=cap(s.joy-2,0,100);text='คุณใช้เวลาพักรับงานเพิ่ม ได้ค่าจ้างสุทธิ '+value+' ทอง แต่แรงและเวลาของคนใกล้ตัวลดลง'}if(id==='aid'){if(e.aidYear===s.age||s.gold>=1000||e.debt<=0)return false;const help=Math.min(e.debt,1800);e.debt=round(e.debt-help);e.aidYear=s.age;text='กองทุนชุมชนช่วยชำระยอดจำเป็น '+help+' ทอง เงินช่วยไม่ใช่รายรับประจำ'}if(id==='family'){if(s.gold<500)return false;s.gold=round(s.gold-500);e.familyFund=round(cap(e.familyFund+500));s.bond=cap(s.bond+2,0,100);text='คุณแบ่ง 500 ทองให้ครอบครัว เงินสำรองที่บ้านเพิ่มขึ้นจริง'}if(id==='repay'){if(s.gold<500||e.debt<=0)return false;const amount=Math.min(500,e.debt);s.gold=round(s.gold-amount);e.debt=round(e.debt-amount);text='คุณชำระเงินต้น '+amount+' ทอง ยอดหนี้เหลือ '+e.debt.toLocaleString('en-US')+' ทอง'}e.actionQuarter=q;add(s,a.name,text);return true}
 function travelCost(s,to){if(to===s.kingdom)return 0;const path=WorldMap.routeBetween(s.kingdom,to),distance=path.slice(1).reduce((n,p,i)=>n+Math.hypot(p[0]-path[i][0],p[1]-path[i][1]),0);return Math.round((350+distance*2.2)*WorldTimeline.impact(s).price)}
 function install(){const scaled=new WeakSet;const effect=o=>{if(!o||typeof o!=='object'||scaled.has(o))return;scaled.add(o);if(Number.isFinite(o.gold))o.gold*=100};for(const e of EVENTS){for(const c of e.choices||[])effect(c.effect)}for(const a of SITUATIONS)for(const c of a[2]||[])effect(c.effect);
  for(const e of EVENTS)if(e.choices.every(c=>c.effect.gold<0)){const old=e.choices[e.choices.length-1];e.choices[e.choices.length-1]={...old,label:e.projectOnly?'ลดขนาดแผนให้ใช้สิ่งที่มีอยู่':'อยู่ช่วยด้วยเวลาแทนค่าใช้จ่าย',effect:e.projectOnly?{joy:-2,projectPath:'scaled'}:{bond:1,joy:-2},success:e.projectOnly?'คุณเลื่อนการขยายและใช้ทรัพยากรที่มี เป้าหมายเดินต่อในขนาดเล็กลง':'คุณบอกตรง ๆ ว่ายังช่วยค่าใช้จ่ายไม่ได้ แต่จะอยู่รับฟังและช่วยตามกำลัง',bondTrust:1,bondMode:'quiet'}}
  for(let i=0;i<JOBS.length;i++){wages[i]=annualPay(JOBS[i]);JOBS[i][3]=wages[i]}
  const labels={gold:'ทอง',health:'สุขภาพ',joy:'ความสุข',bond:'สัมพันธ์',wisdom:'ปัญญา',power:'กำลัง',magic:'เวท',fame:'ชื่อเสียง',standing:'ฐานะ',localTrust:'ความไว้ใจ'};for(const e of EVENTS)for(const c of e.choices||[]){const hints=Object.entries(c.effect||{}).filter(([key,value])=>labels[key]&&Number.isFinite(value)).map(([key,value])=>labels[key]+' '+(value>0?'+':'')+value.toLocaleString('en-US'));if(hints.length)c.hint=hints.join(' · ')}
  const prices={meal:1560,gift:600,clinic:2400,course:4800,hobby:1800,garden:900,trip:3600,donation:1200,tools:4200,renovate:12000,house:180000,heritage:960};for(const p of LifeSpending.catalog)p.cost=prices[p.id]||p.cost*100;
  const itemPrices={'bookcase':180,'desk':250,'reading-lamp':35,'flute':70,'violin':650,'bed':650,'hearth':3400,'telescope':1200};for(const p of LifeChoices.shop)p.cost=itemPrices[p.id]||p.cost*35;for(const p of LifeChoices.petCatalog){p.cost*=20;p.upkeep*=120}for(const p of LifeChoices.focusCatalog){if(p.cost)p.cost*=30;if(p.income)p.income*=100}for(const p of LifeProjects.catalog)p.costPerQuarter*=100;for(const p of Livelihood.businessCatalog){p.cost*=1000;p.revenue*=2800;p.costs*=1800}for(const a of LifeBonds.actions||[])a.cost*=20;
  const house=EVENTS.find(e=>e.id==='money-house');if(house){house.choices[0].effect.gold=-180000;house.choices[0].hint='ทอง −180,000 · ความสุข +10 · สัมพันธ์ +4'}
 }
 function validAccounts(a){const number=n=>Number.isFinite(n)&&n>=0&&n<=1e9,record=r=>r&&Object.keys(r).length===Object.keys(blank()).length&&Object.keys(blank()).every(k=>number(r[k]));return a&&a.version===1&&Number.isInteger(a.year)&&a.year>=500&&a.year<=21000&&Number.isInteger(a.giftYear)&&a.giftYear>=-1&&a.giftYear<=a.year&&record(a.current)&&Array.isArray(a.closed)&&a.closed.length<=12&&a.closed.every(r=>Number.isInteger(r.year)&&r.year>=500&&r.year<a.year&&record(Object.fromEntries(Object.entries(r).filter(([k])=>k!=='year'))))}
 function valid(s){const e=s.economy;if(e===undefined)return true;if(e.accounts!==undefined&&!validAccounts(e.accounts))return false;const num=(x,a=0,b=1e9)=>Number.isFinite(x)&&x>=a&&x<=b,int=(x,a=-1,b=120000)=>Number.isInteger(x)&&num(x,a,b);return e&&e.version===1&&typeof e.migrated==='boolean'&&['lean','standard','comfort'].includes(e.budget)&&['family','rent','guild'].includes(e.housing)&&num(e.debt)&&num(e.familyFund)&&num(e.familyArrears,0,250000)&&int(e.lastQuarter)&&int(e.lastYear)&&int(e.missed,0)&&int(e.actionQuarter)&&int(e.aidYear)&&Array.isArray(e.history)&&e.history.length<=24&&e.history.every(x=>num(x.age,0,10000)&&typeof x.title==='string'&&x.title.length<200&&typeof x.text==='string'&&x.text.length<1200)&&(e.last===null||e.last&&Object.values(e.last).every(x=>num(x,-1e9,1e9)))}
 function canPatron(s){const a=accounts(s),fund=ensure(s).familyFund;if(Engine.biological(s)<18||a.giftYear===a.year||!giver(s)||fund<50000||RaceDrives.cashless(s))return false;return s.race===0?(s.humanOrigin?.birthRank??s.heritage?.birthRank??s.rank)>=6&&(s.humanOrigin?.favor??60)>=50:SpeciesSociety.metrics(s).access>=75&&SpeciesSociety.metrics(s).voice>=55}
 function patronAmount(s){return round(Math.min(ensure(s).familyFund*.02,s.race===0&&(s.humanOrigin?.birthRank??s.rank)===7?30000:12000))}
 function receivePatron(s){if(!canPatron(s))return false;const amount=patronAmount(s),a=accounts(s),e=ensure(s);e.familyFund=round(e.familyFund-amount);s.gold=round(cap(s.gold+amount));a.giftYear=a.year;if(s.race===0&&s.humanOrigin)s.humanOrigin.favor=Math.max(0,s.humanOrigin.favor-6);else{const origin=SpeciesSociety.ensure(s);origin.duty=Math.min(100,origin.duty+8);s.lifeChoices.localTrust=Math.max(0,s.lifeChoices.localTrust-3)}record(s,'support',amount);add(s,'ส่วนแบ่งจากทุนของกลุ่ม',giver(s).name+'รับรองส่วนแบ่ง '+amount.toLocaleString('th-TH')+' ทองจากทุนเดิมของกลุ่ม สิทธิที่ได้รับผูกกับความไว้ใจและพันธะต่อบ้าน');return true}
 function decorate(s,e){if(e.familyEndowment){const who=giver(s),amount=patronAmount(s);return {...e,title:'ส่วนแบ่งที่'+(who?.name||'กลุ่ม')+'รับรองให้',text:'ทุนของกลุ่มกันส่วนแบ่ง '+amount.toLocaleString('th-TH')+' ทองไว้ให้สมาชิกที่ยังมีสิทธิ คุณรับได้ แต่การพึ่งทุนนี้มีพันธะและกระทบความไว้ใจของกลุ่ม',choices:e.choices.map(c=>c.acceptPatron?{...c,hint:'โอนจริง '+amount.toLocaleString('th-TH')+' ทองจากทุนของกลุ่ม · '+(s.race===0?'ความไว้ใจของตระกูล −6':'พันธะต่อกลุ่ม +8 ความไว้ใจ −3')}:c)}}if(!e.familyGift)return e;const who=giver(s),amount=giftAmount(s),native=RaceDrives.cashless(s);return {...e,title:'ส่วนที่'+(who?.name||'ผู้ดูแล')+'กันไว้ให้',text:(who?.name||'ผู้ดูแล')+'กัน'+(native?'ส่วนของแหล่งดำรงชีวิต':amount.toLocaleString('th-TH')+' ทอง')+'ให้คุณ คุณยังฝากไว้กับส่วนจำเป็นของกลุ่มก่อนได้',choices:e.choices.map(c=>c.acceptGift?{...c,hint:native?'แหล่งถิ่น +6 · เป็นส่วนแบ่งจากผู้ดูแล':'รับ '+amount.toLocaleString('th-TH')+' ทอง · หักจากเงินสำรองของบ้านจริง'}:c)}}
 return {canPatron,patronAmount,receivePatron,decorate,giver,regions,wages,actions,ensure,birth,migrate,tax,salary,quote,quarter,setPlan,action,travelCost,install,valid,accounts,record,annual,canGift,giftAmount,receiveGift};
})();

/* epoch-controls.js */
'use strict';
// Register canonical USD prices before installing the new, already-denominated world decisions.
Economy.install();WorldTimeline.install();
const EpochUI=(()=>{
 const num=n=>(Number(n)||0).toLocaleString('en-US',{maximumFractionDigits:0}),labels={expedition:'ค่าคุ้มครองและบำรุงอุปกรณ์สมาคม',housing:'ที่พัก / บำรุงถิ่น',food:'อาหารและแหล่งดำรงชีวิต',utilities:'น้ำ พลังงาน และการบำรุง',health:'สุขภาพและการดูแล',transport:'การเดินทาง',needs:'ของจำเป็น'};
 function panel(s){const e=Economy.ensure(s),w=WorldTimeline.impact(s),y=Economy.annual(s),known=w.threats.filter(t=>t.phase==='active'||s.worldTimeline.office===t.faction),threat=known[0];return `<section class="epoch-panels">${RaceDrives.cashless(s)?`<button class="panel money-overview" id="openEconomy"><span class="eyebrow">แหล่งถิ่นที่เลี้ยงร่าง · ปี ${y.year}</span><strong>${Math.round(s.raceDrives.resource)} <small>/100</small></strong><span>${esc(SpeciesSociety.profile(s).res)}</span><small>เงินจากการแลกเปลี่ยน ${num(s.gold)} ทอง · ดูวิถี ↗</small></button>`:`<button class="panel money-overview" id="openEconomy"><span class="eyebrow">เงินส่วนตัว · 1 ทอง = 1 USD</span><strong>${num(s.gold)} <small>ทอง</small></strong><span>ปี ${y.year} · รายรับสุทธิสะสม ${num(y.income)} ทอง</span><small>ภาระและการใช้จ่ายปีนี้ ${num(y.cost)} ทอง${e.debt?' · หนี้ '+num(e.debt):''} · ดูบัญชีรายปี ↗</small>${Engine.biological(s)<16?'<small>ทุนของ'+esc(s.race===0?'ครอบครัว':SpeciesSociety.profile(s).group)+'แยกจากเงินที่มอบให้คุณ</small>':''}</button>`}<button class="panel epoch-overview ${w.severity>.4?'epoch-danger':''}" id="openWorldYear"><span class="eyebrow">โลกที่เกิดขึ้นในขณะนี้</span><strong>ปี ${w.year}</strong><span>${esc(threat?.name||w.omen)}</span><small>ราคาท้องถิ่น ${Math.round(w.price*100)}% · อ่านข่าวปีนี้ ↗</small></button></section>`}
 function bind(){if($('#openEconomy'))$('#openEconomy').onclick=money;if($('#openWorldYear'))$('#openWorldYear').onclick=world}
 function refresh(view){save();clock.reset();render();view()}
 function money(){const s=state,e=Economy.ensure(s),q=Economy.quote(s),y=Economy.annual(s),locked=s.dead||!s.accepted||s.outcome||s.calendar?.pending||Engine.biological(s)<16;modal(`<section class="epoch-dialog"><span class="eyebrow">บัญชีชีวิต · ปี ${y.year} · 1 ทอง = 1 USD</span><h2>เงินส่วนตัว ${num(s.gold)} ทอง</h2><p class="money-explainer">สรุปเป็นรายปี รายรับและภาระทยอยเกิดทุกสามเดือนตามปฏิทินจริงของโลก เงินครอบครัวไม่ได้เป็นเงินพร้อมใช้ของคุณ</p><div class="economy-totals"><div><small>รายรับสุทธิสะสมปีนี้</small><b>${num(y.income)}</b></div><div><small>ภาระและการใช้จ่ายปีนี้</small><b>${num(y.cost)}</b></div><div><small>ค่าครองชีพตามแผนต่อปี</small><b>${num(q.monthly*12)}</b></div><div><small>หนี้ส่วนตัว</small><b class="money-loss">${num(e.debt)}</b></div><div><small>${s.race!==0?'ทุนส่วนรวมของ'+esc(SpeciesSociety.profile(s).group):'เงินสำรองของครอบครัว'}</small><b>${num(e.familyFund)}</b></div><div><small>ค่าจ้างเต็มปีโดยประมาณ</small><b>${Adventures.isCareer(s)?'รับตามงานสำเร็จ':num(Economy.salary(s))}</b></div></div>${e.familyArrears>0?`<p class="economy-warning">บ้านยังขาดค่าใช้จ่าย ${num(e.familyArrears)} ทอง · แยกจากหนี้ส่วนตัว</p>`:''}<h3 class="year-ledger-title">ปี ${y.year} · รับและจ่ายจริงสะสม</h3><dl class="account-lines"><div><dt>รายรับงานก่อนภาษี</dt><dd>+${num(y.gross)}</dd></div><div><dt>ภาษีจำลอง</dt><dd>−${num(y.tax)}</dd></div><div><dt>ส่วนที่บ้านมอบให้จริง</dt><dd>+${num(y.support)}</dd></div><div><dt>รับอื่นและขายทรัพย์สิน</dt><dd>+${num(y.otherIncome)}</dd></div><div><dt>ค่าครองชีพและบิล</dt><dd>−${num(y.expenses)}</dd></div><div><dt>ซื้อของ เสบียง และภาระอื่น</dt><dd>−${num(y.otherSpend)}</dd></div><div><dt>ดอกเบี้ยหนี้ที่เกิดขึ้น</dt><dd>−${num(y.interest)}</dd></div><div><dt>คืนเงินต้น</dt><dd>−${num(y.principal)}</dd></div><div><dt>ค่าใช้จ่ายที่เงินยังไม่ถึง</dt><dd>${num(y.shortfall)}</dd></div></dl><p class="annual-budget-note">ค่าครองชีพเป็นงบเต็มปี ยอดสะสมข้างบนคิดเฉพาะช่วงที่ผ่านไป หนี้ค้างมีดอกเบี้ย 18% ต่อปี ส่วนที่เกินวงเงินไม่ได้ยืมเพิ่มและทำให้บางบริการต้องเลื่อน การขายทรัพย์สินเป็นเงินรับครั้งเดียว</p>${RaceDrives.cashless(s)?'<p class="money-explainer">ร่างและถิ่นนี้ใช้แหล่งดำรงชีวิตตามธรรมชาติ ไม่มีเงินเดือนหรือค่าเช่าเมือง งานที่รับยังมีต้นทุนแหล่งถิ่น</p>':''}${Economy.canPatron(s)?`<button class="secondary" id="requestPatron" ${locked?'disabled':''}>คุยเรื่องส่วนแบ่งจากทุนเดิมของกลุ่ม ${num(Economy.patronAmount(s))} ทอง →</button>`:''}<h3>เลือกภาระที่รับไหวในหนึ่งปี</h3><div class="epoch-selectors"><label>แผนชีวิต<select id="economyBudget" ${locked?'disabled':''}>${[['lean','ประหยัด · ลดส่วนที่ลดได้ 18%'],['standard','ใช้ตามความจำเป็น'],['comfort','สะดวกสบาย · เพิ่มงบ 40%']].map(([id,label])=>`<option value="${id}" ${e.budget===id?'selected':''}>${label}</option>`).join('')}</select></label><label>ที่พัก<select id="economyHousing" ${locked||q.native||s.spending.home.owned?'disabled':''}><option value="family" ${e.housing==='family'?'selected':''}>แบ่งค่าใช้จ่ายในที่พักร่วม</option><option value="rent" ${e.housing==='rent'?'selected':''}>เช่าที่พักแยก</option>${Adventures.ensure(s).member&&!s.children?`<option value="guild" ${e.housing==='guild'?'selected':''}>ที่พักรวมของสมาคม</option>`:''}</select></label></div><dl class="account-lines">${q.rows.map(r=>`<div><dt>${esc(s.race!==0?SpeciesSociety.costLabel(s,r.id,labels[r.id]):labels[r.id])}</dt><dd>${num(r.monthly*12)} / ปี</dd></div>`).join('')}</dl><button class="secondary" id="economyHousingLevels">ที่พักห้าระดับและค่าบำรุง →</button><h3>หาเงินและจัดการภาระ</h3><div class="choices">${Economy.actions.map(a=>`<button class="choice" data-economy-action="${a.id}" ${locked||e.actionQuarter===s.calendar.count||RaceDrives.cashless(s)&&['shift','aid'].includes(a.id)?'disabled':''}><span><b>${a.name}</b><small>${a.description}</small></span></button>`).join('')}</div><p id="economyError" class="money-loss" role="status"></p><p class="money-explainer">รับงานเพิ่มหนึ่งครั้งต่อสามเดือน เงินเพิ่มต้องแลกด้วยกำลังและเวลาพัก</p><button class="secondary" id="economySpending">ใช้เงินและลงทุน →</button>${y.last?`<details><summary>ปีที่ปิดบัญชีแล้ว ${y.last.year}</summary><p>รายรับสุทธิ ${num(y.last.gross-y.last.tax+y.last.support+y.last.otherIncome)} ทอง · ค่าใช้จ่ายและดอกเบี้ย ${num(y.last.expenses+y.last.otherSpend+y.last.interest)} ทอง</p></details>`:''}<details><summary>รายการที่เกิดขึ้นแล้ว</summary>${e.history.map(h=>`<p><b>อายุ ${h.age} · ${esc(h.title)}</b><br>${esc(h.text)}</p>`).join('')}</details></section>`);$('#economyBudget').onchange=ev=>{if(Economy.setPlan(s,'budget',ev.target.value))refresh(money)};$('#economyHousing').onchange=ev=>{if(Economy.setPlan(s,'housing',ev.target.value))refresh(money)};document.querySelectorAll('[data-economy-action]').forEach(b=>b.onclick=()=>{if(Economy.action(s,b.dataset.economyAction))refresh(money);else $('#economyError').textContent='เงื่อนไขยังไม่ครบ หรือเงินส่วนตัวยังไม่พอ'});$('#economySpending').onclick=SpendingUI.open;$('#economyHousingLevels').onclick=HousingUI.open;if($('#requestPatron'))$('#requestPatron').onclick=()=>{const e=EVENTS.find(e=>e.familyEndowment);if(!locked&&Engine.eligible(s,e)){s.event={...Economy.decorate(s,e),context:WorldLore.context(s,s.calendar.count)};s.calendar.pending=true;$('#modal').close();save();render()}}}
 function offer(id){const s=state,event=EVENTS.find(e=>e.officeOnly===id);if(!event||s.dead||s.outcome||s.calendar.pending||!Engine.eligible(s,event))return;s.event={...WorldTimeline.decorate(s,event),context:WorldLore.context(s,s.calendar.count)};s.calendar.pending=true;$('#modal').close();save();render()}
 function world(){const s=state,w=WorldTimeline.ensure(s),report=WorldTimeline.impact(s),known=report.threats.filter(t=>t.phase==='active'||w.office===t.faction);modal(`<section class="epoch-dialog"><span class="eyebrow">พงศาวดารที่คุณรับรู้ในชีวิตนี้</span><h2>ปี ${report.year}</h2><h3>${esc(report.omen)}</h3><p>${esc(report.news)}</p><div class="epoch-chronicle">${known.map(a=>`<article class="${a.phase==='active'&&a.mode==='attack'?'epoch-danger':''}"><small>ข่าวที่มาถึงในปี ${report.year}</small><h3>${esc(a.name)}</h3><p>${esc(a.phase==='warning'?'กองทัพฝ่ายของคุณเริ่มเตรียมกำลัง สภารอฟังว่าจะใช้กำลังหรือเจรจา':a.mode==='peace'?'การเจรจาเปิดทางให้หลายฝ่ายกลับมาพูดคุย':a.mode==='delay'?'กองทัพหยุดเพื่อจัดการภาระในดินแดน':a.text)}</p></article>`).join('')}</div><h3>สิ่งที่อาณาจักรเผชิญในปีนี้</h3><div class="epoch-regions">${KINGDOMS.map((k,i)=>{const r=WorldTimeline.impact(s,i);return `<div class="${i===s.kingdom?'current':''}"><b>${esc(k[0])}${i===s.kingdom?' · คุณอยู่ที่นี่':''}</b><span>ราคา ${Math.round(r.price*100)}% · งาน ${Math.round(r.jobs*100)}%</span><small>${r.severity>.5?'แนวรบและการอพยพ':r.severity>.15?'เสบียงและการค้าได้รับผล':'ผลกระทบทางอ้อม'}</small></div>`}).join('')}</div><h3>เรื่องที่ผ่านมาระหว่างชีวิตนี้</h3>${w.history.filter(h=>h.year<=report.year).slice(0,16).map(h=>`<p><b>ปี ${h.year}</b> · ${esc(h.title)} · ${esc(KINGDOMS[h.realm][0])}</p>`).join('')||'<p>ยังไม่มีข่าวที่บันทึกไว้</p>'}<details><summary>บทบาทที่คุณอาจรับผิดชอบในสังคม</summary><p>ผู้ที่โตเต็มวัย มีผลงานและได้รับความไว้ใจสามารถขอรับบทบาทดูแลส่วนรวมได้</p>${WorldTimeline.offices.map(o=>{const e=EVENTS.find(e=>e.officeOnly===o.id);return e&&Engine.eligible(s,e)?`<button class="secondary" data-world-office="${o.id}">${esc(o.name)}</button>`:''}).join('')}</details></section>`);document.querySelectorAll('[data-world-office]').forEach(b=>b.onclick=()=>offer(b.dataset.worldOffice))}

 return {panel,bind,money,world,offer};
})();

/* race-drives.js */
'use strict';
const RaceDrives=(()=>{
 // Desires describe inherited pressures, not compulsory morality. Every row has an alternative.
 const rows=[
 ['สร้างชื่อที่เลือกเอง','ชื่อสกุลอาจกำหนดประตูที่เปิดให้ แต่คุณยังเลือกงานและคนที่อยู่ข้างกัน','สืบเส้นทางของบ้าน','สร้างชีวิตร่วมหลายเผ่า','ทิ้งชื่อสกุลเพื่อทางของตน'],
 ['ฟังดาวก่อนมันเลือน','ช่วงชีวิตยาวทำให้คำสัญญาถูกส่งต่อข้ามคนหลายรุ่น','รักษาทำนองดาวของวงศ์','แบ่งดวงดาวให้ผู้มีชีวิตสั้น','แต่งทำนองที่บรรพชนไม่รู้จัก'],
 ['รักษาทางของราก','รากเก่าจำการตัดไม้ได้ แต่ป่าใหม่อาจต้องมีทางให้ผู้มาเยือน','ปิดเขตรากเก่าจากคนนอก','เปิดแนวเดินที่ไม่บาดราก','แยกตัวจากเสียงของป่า'],
 ['เป็นเจ้าของเงาของตน','โถงมืดปลอดภัย แต่คำสั่งของตระกูลอาจตามถึงทุกเงา','สืบวิชาเงาของตระกูล','ทำทางให้ผู้กลัวความมืด','เลิกยืมเงาของบรรพชน'],
 ['สร้างสิ่งที่อยู่พ้นอายุช่าง','หินจำแรงที่เคาะ ชื่อช่างจึงเป็นทั้งเกียรติและภาระ','สร้างแกนยักษ์กลให้ภูเขา','สร้างเครื่องมือที่หลายร่างใช้ได้','ตีงานซึ่งไม่มีสภาอนุมัติ'],
 ['มีทางหนีที่ตนเลือก','กลิ่นหลายสายดึงให้รักษาหน้าของฝูงพร้อมกับความลับของตน','เป็นผู้รักษากลิ่นทางของวงศ์','พาคนนอกผ่านทางลวงโดยสมัครใจ','เลิกซ่อนตัวหลังเรื่องเล่าของเผ่า'],
 ['ได้รับเสียงตอบจากฝูง','เสียงหอนดึงให้ตอบ แม้คุณอาจไม่อยากร่วมการล่า','นำฝูงรักษาแนวหากิน','แบ่งเขตล่ากับฝูงอื่น','ออกหากินลำพังโดยไม่ตัดสายเรียก'],
 ['มีที่สูงที่ไม่มีใครยึด','ทางแคบเหมาะกับร่าง แต่การครอบครองทุกคานทำให้เพื่อนไม่มีทางผ่าน','คุมทางเรือนยอดของตระกูล','เว้นคานร่วมให้สัตว์เล็ก','ออกค้นชานที่ไม่มีชื่อเจ้าของ'],
 ['ให้เสียงตนถึงกระแสลึก','แนวปะการังเป็นที่ฟักและพรมแดนในเวลาเดียวกัน','ทวงคืนกระแสของรัง','เปิดร่องน้ำให้คนสองฝั่ง','ว่ายพ้นคำเรียกของบัลลังก์'],
 ['ควบคุมไฟก่อนสืบมงกุฎ','สายเลือดมังกรคาดหวังเสียงคำราม แต่ร่างคุณมีขอบเขตของมัน','รับช่วงรังและคำสาบาน','ใช้ไฟบังหนาวให้เผ่าอื่น','ไม่ยอมให้สายเลือดกำหนดงาน'],
 ['เก็บฤดูหนึ่งไว้ในปีก','น้ำหวานและอายุของดอกไม่รอคำสั่งจากผู้ยิ่งใหญ่','คุ้มครองวงดอกของฝูง','ช่วยพาละอองข้ามสวนต่างเผ่า','เลือกฤดูของตนแทนฤดูที่ถูกสั่ง'],
 ['ให้เกียรติอยู่หลังการปะทะ','เสียงกีบและกลิ่นท้าทายปลุกแรงสู้ แต่การไว้ชีวิตก็ต้องใช้กำลัง','รักษาชื่อค่ายด้วยการรบ','เป็นผู้หยุดการล่าล้างค่าย','วางอาวุธแล้วสร้างทางของตน'],
 ['มีอุโมงค์ซึ่งไม่ต้องหลบใคร','การถูกไล่จากถิ่นทำให้เสบียงและเครื่องมือมีค่ามากกว่าคำชม','รวบรวมค่ายทวงพื้นที่จากมนุษย์','แลกวิชาและทางหนีกับมนุษย์','ตั้งโพรงอิสระที่ไม่ร่วมการบุก'],
 ['คงแกนโดยไม่กลืนทุกอย่าง','กลิ่นสารอาหารดึงให้แผ่ร่าง แต่สิ่งที่ดูดรับอาจเป็นชีวิตอื่น','แผ่แอ่งให้แกนของฝูง','แบ่งตะกอนโดยไม่กลืนผู้มาเยือน','แยกหยดออกค้นรูปใหม่'],
 ['รู้ว่าชีวิตนี้เป็นของใคร','ร่างที่ตื่นอาจมีความทรงจำซึ่งไม่ได้ขอรับ','ค้นผู้ที่ปลุกร่างขึ้นมา','คุ้มครองผู้ตื่นรู้ที่ไม่มีเจ้าของ','ทิ้งคำสั่งเก่าและเลือกชื่อใหม่'],
 ['ทำให้คำสาบานมีน้ำหนัก','เขารับรู้ถ้อยคำผูกมัด แต่การบังคับสัญญาทำให้ผู้อื่นไม่มีทางถอย','รวมพันธะเพื่อสภาปีศาจ','ทำข้อตกลงที่ทั้งสองฝ่ายถอนตัวได้','ตัดเขตอำนาจจากสภาเขาดำ'],
 ['มีเงาที่ไม่ต้องเกาะใคร','ขอบร่างชอบแสงอ่อน แต่เงาของผู้อื่นไม่ใช่ทรัพย์ของคุณ','เชื่อมเงาเป็นอาณาเขตของเผ่า','ทำเงากำบังให้ผู้หนีสงคราม','คงรูปโดยไม่ยืมเงาเจ้าผู้ครอง'],
 ['แยกความฝันตนจากเหยื่อ','ละอองฝันเลี้ยงปีก แต่ความกลัวของผู้หลับอาจเป็นอาหารที่เลือกไม่กินได้','เก็บความฝันบำรุงรัง','กินเพียงฝันที่ผู้หลับยอมแบ่ง','สร้างทำนองจากความฝันตน'],
 ['คงความเย็นโดยไม่หยุดทุกชีวิต','อุณหภูมิต่ำรักษาผลึก แต่ร่างอุ่นข้างกันอาจทนไม่ไหว','ขยายเขตเหมันต์ของแกน','เว้นร่องอุ่นให้เผ่าอื่นผ่าน','ค้นวิธีคงร่างนอกฤดูหนาว'],
 ['เลือกว่าสายเลือดจะผูกใคร','ชีพจรใกล้ตัวชวนสร้างพันธะ แต่ไม่ใช่ทุกชีวิตยินยอมให้ผูก','รวมพันธะโลหิตของสกุล','รับพันธะเฉพาะผู้สมัครใจ','หาวิธีอยู่โดยไม่ยืมชีพจร'],
 ['มีใบหน้าที่ไม่ต้องสะท้อนอำนาจ','ผิวรับภาพคนรอบตัวจนการจำตนยากกว่าการเลียนใคร','เก็บหน้าของผู้ครองนคร','สะท้อนความจริงให้หลายฝ่ายเห็น','รักษารอยร้าวซึ่งเป็นของตน'],
 ['ให้ข่าวกลับถึงรัง','แรงลมพาข่าวเร็ว แต่ข่าวอาจพากองทัพมาถึงรังอีกแห่ง','เป็นเสียงข่าวของกองทัพปีศาจ','ส่งคำเตือนให้ทั้งสองแนวรบ','เก็บเสียงซึ่งไม่ขึ้นกับผู้สั่ง'],
 ['เหลือแกนอุ่นหลังไฟมอด','เถ้าจำการเผาได้ แต่ไม่จำเป็นต้องปลุกไฟซ้ำทุกครั้ง','รับเถ้าจากสนามรบคืนเผ่า','ทำแนวอุ่นให้ชีวิตงอกหลังไฟ','ก่อรูปจากเถ้าที่ตนเลือก'],
 ['เลือกว่าปีกจะคุกเข่าให้ใคร','รอยคำสั่งบนปีกยังตอบรับแม้เจ้าของร่างอยากไปอีกทาง','กลับรับคำสั่งสำนักฟ้า','บังปีกให้ผู้ที่ถูกฟ้าปฏิเสธ','ประกาศเสรีภาพจากเทพทุกองค์'],
 ['มีหินอุ่นที่เฝ้าได้','ร่างเย็นต้องแดด แต่แหล่งอุ่นก็เป็นทางของสัตว์อื่น','คุมแนวผึ่งเกล็ดของรัง','แบ่งหินอุ่นเป็นเวลา','เลือกทางน้ำแทนเขตที่ต้องแย่ง'],
 ['ไปถึงลมที่รังไม่รู้จัก','ขอบหน้าผาดึงให้ปกป้องลูก แต่ฟ้าก็ชวนให้ออกไกล','คุมช่องลมรอบรัง','ส่งข่าวให้รังต่างเผ่า','บินออกโดยไม่รับยศของฝูง'],
 ['ให้หนวดจำทางปลอดภัย','ช่องแคบคุ้มร่างเล็ก แต่การเก็บเสบียงเกินจำเป็นปิดทางของผู้อื่น','ขยายอุโมงค์และคลังกลุ่ม','ทำร่องหนีให้ร่างเล็กหลายเผ่า','ตามกลิ่นไปพ้นผนังเดิม'],
 ['ออกจากทางที่ผู้อื่นวาง','เสียงสะท้อนช่วยจำถ้ำ แต่ผังที่สืบมาอาจเป็นคอก','เป็นผู้เฝ้าทางวงกต','เปิดช่องปลอดภัยให้ผู้หลงทาง','เปลี่ยนผังแทนเดินตามมัน'],
 ['รักษาเกล็ดกับทางน้ำ','แรงน้ำบอกการบุกรุก แต่ไม่ใช่ทุกผู้ผ่านคือศัตรู','คุมแอ่งฟักและทางเลื้อย','เปิดร่องแลกเสบียงกับฝั่งบก','ออกผลัดเกล็ดไกลบัลลังก์'],
 ['ควบคุมก้ามไม่ให้ล่าทุกสัญญาณ','แรงสั่นปลุกการโจมตี แต่หนวดเรียนรู้สัญญาณสงบได้','เป็นแนวล่าของรัง','ส่งสัญญาณก่อนใช้ก้าม','ฝึกแรงที่ไม่ขึ้นกับจังหวะฝูง'],
 ['ให้รากไปถึงโดยไม่รัดทุกสิ่ง','ดินพาเสียงของผู้อื่นมา รากอาจรับฟังหรือแย่งน้ำ','ขยายรากรักษาผืนป่า','แบ่งน้ำกับรากต่างสาย','ตัดรากหนึ่งเส้นไปเริ่มเอง'],
 ['มีเจตจำนงเหนือคำสั่งแกน','แรงเก่าสั่งให้ยกและทำลาย แต่แกนใหม่อาจเลือกวางลง','รักษาโถงที่ช่างฝากไว้','สร้างทางให้ร่างเปราะผ่าน','ลบคำสั่งเจ้าของจากแกน'],
 ['คงรูปโดยไม่ยึดทั้งโอเอซิส','ลมแยกร่างและพาไปหาแอ่งชื้นซึ่งเผ่าอื่นต้องใช้','ขยายวงทรายคุ้มถิ่น','เว้นแนวน้ำให้ผู้เดินทาง','ออกเป็นพายุที่ไม่ขึ้นกับผู้เรียก'],
 ['มีฝันที่ไม่มีผู้สั่งให้ฝัน','ฝันของผู้หลับพาร่างเปลี่ยน แต่ความคิดตนก็มีค่า','สืบคำทำนายรังฝัน','กันฝันร้ายโดยไม่ครองผู้หลับ','ก่อแกนจากฝันที่เลือกเอง'],
 ['ใช้เขาแทนการถูกท้าทาย','ความอับอายชวนตอบด้วยแรง แต่เกียรติอาจอยู่ในสิ่งที่ไม่ตี','รักษาแนวรบของวงศ์เขา','เป็นโล่ให้ผู้ที่สู้ไม่ไหว','ออกจากวงประลองเพื่อฝึกตน'],
 ['ไม่ให้แสงกลืนเสียงของตน','สำนักดาวคาดหวังคำทำนาย แต่คำตอบอาจยังไม่เกิด','รักษาระเบียบสำนักดาว','แบ่งแสงแก่ผู้ไม่มีสำนัก','อยู่โดยไม่ทำนายอนาคตใคร'],
 ['มีอาณาเขตที่กลิ่นตนคงอยู่','กลิ่นผู้บุกรุกปลุกไฟในอก แต่ความหิวกับอำนาจไม่ใช่สิ่งเดียวกัน','ขยายรังและขุมทรัพย์ด้วยกำลัง','รักษาเขตโดยตกลงกับกอบลิน','บินพ้นสมบัติที่บรรพชนทิ้งไว้'],
 ['คืนไฟโดยไม่วนเผาทุกครั้ง','แกนเกิดใหม่จำความร้อนเก่าได้ แต่โลกที่กลับมาไม่เหมือนเดิม','สืบวงเพลิงและรังเดิม','ให้ความอุ่นฟื้นถิ่นหลังไฟ','เกิดใหม่โดยไม่รับคำสาบานเก่า'],
 ['แยกเสียงของหยดนับพัน','ฝูงเจลเกื้อหนุนแกน แต่การรวมร่างอาจทำเสียงตนหาย','รวมแอ่งเป็นร่างใหญ่ของฝูง','ทำช่องให้หยดอื่นแยกออกได้','รักษาแกนเดี่ยวในทางใหม่'],
 ['ไปถึงทุ่งก่อนหญ้าหมด','ฝูงต้องทางกว้าง แต่การยึดทุ่งตลอดฤดูทำให้ผู้อื่นอด','นำฝูงคุมทางอพยพ','ตกลงฤดูผ่านกับผู้ตั้งถิ่น','วิ่งพ้นธงค่ายแล้วเลือกจังหวะเอง'],
 ['รับรู้ทุกสายใยโดยไม่ดักทุกผู้ผ่าน','แรงสั่นแยกเหยื่อกับแขกได้เมื่อคุณยอมฟังให้พอ','ขยายชานใยของวงศ์','เปิดช่องผ่านให้เผ่าอื่น','ตัดเส้นรับคำสั่งแล้วทอแบบตน'],
 ['ไม่ให้ต้นน้ำลืมปลายน้ำ','แอ่งฟักต้องน้ำสะอาด แต่การปิดน้ำทั้งสายทำให้กลุ่มอื่นเสียถิ่น','คุมหัวน้ำของรัง','ตกลงรอบน้ำกับสองฝั่ง','ตามกระแสไปพ้นวงฟักเดิม'],
 ['มีผู้สวมที่ไม่ใช่เจ้าของ','คำสั่งให้รับคมยังอยู่ แต่ร่างโลหะอาจเลือกผู้ร่วมสู้','คุ้มครองคำสาบานของเกราะ','เปิดทางให้ผู้ไร้อาวุธ','ปลดชื่อเจ้าของจากแผ่นอก'],
 ['ให้ใยตนไม่กลืนทุกกลิ่น','อาหารจากความผุเลี้ยงรัง แต่ร่างที่ยังมีชีวิตไม่ใช่ปุ๋ยเสมอไป','แผ่หัวเชื้อใต้ถิ่นใหม่','ย่อยเฉพาะสิ่งที่คืนสู่ดินแล้ว','แยกใยเดี่ยวเพื่อฟังกลิ่นใหม่'],
 ['รักษาแสงที่ผู้จากไปจำได้','ชื่อเก่าอาจขอให้รอ แต่ผู้ถือโคมยังเลือกเดินต่อได้','เฝ้าจุดยึดของบรรพชน','พาวิญญาณต่างเผ่าผ่านทางมืด','เลือกแสงซึ่งไม่มาจากคำสั่งเก่า'],
 ['มีข้อความที่ไม่ถูกใช้เขียนสงคราม','หมึกซึมได้ทุกสัญญา แต่การบันทึกก็เป็นการเลือกข้าง','เก็บคำสั่งของหอหมึก','เปิดถ้อยคำที่ผู้มีอำนาจปิดไว้','เขียนชื่อและขอบร่างของตน'],
 ['มีที่พักซึ่งร่างไม่ทำลาย','น้ำหนักช่วยย้ายภูเขา แต่ร่างเล็กต้องทางซึ่งไม่สั่นทุกก้าว','รักษาหุบเขาของวงศ์ใหญ่','ทำจุดพักให้ร่างเล็กและใหญ่','ออกค้นถิ่นที่ไม่ต้องรับยศ'],
 ['มีโพรงซึ่งไม่ต้องฟังเสียงล่า','หูรับภัยไกล แต่ความกลัวอาจทำให้ไม่เคยลองทางใหม่','ขยายแนวโพรงหลบภัย','ส่งเสียงเตือนให้ผู้ถูกล่าต่างเผ่า','ออกสำรวจโดยเว้นทางกลับไว้'],
 ['ไม่ต้องเป็นเงาของมังกรเสมอ','กลิ่นมังกรให้ความปลอดภัยและทำให้ถูกใช้เป็นคนแรกในทางเสี่ยง','สืบหน้าที่เฝ้ารังมังกร','ต่อรองสิทธิของโพรงกับมังกร','สร้างชื่อที่ไม่มีนายเหนือรัง'],
 ['ให้เสียงตนพ้นการแย่งรัง','เสียงเรียกดึงคู่และขับแขกได้ แต่คุณเลือกได้ว่าจะส่งเพื่ออะไร','คุมแนวรังด้วยเสียงข่ม','ร้องเตือนพายุให้ผู้ผ่าน','บินออกสร้างทำนองที่ไม่ท้ารบ'],
 ['เลือกว่าฝั่งใดเป็นบ้าน','ผิวเก็บกลิ่นทะเลไว้ แม้แผ่นดินจะชวนให้ผูกพัน','เฝ้าแนวถอดผิวของฝูง','รักษาจุดพบกันของบกกับน้ำ','ออกเดินตามกระแสโดยไม่ฝากผิวให้ใคร'],
 ['มีแอ่งที่กีบไม่ต้องหนี','ร่างจำการดึงเหยื่อลงน้ำได้ แต่ฝูงก็อยู่ได้ด้วยเส้นทางที่ไม่ล่าแขก','คุมแอ่งลึกและล่าเพื่อฝูง','คุ้มครองผู้ข้ามโดยไม่ดึงลงน้ำ','ออกเป็นฝูงเล็กที่ไม่สืบพิธีล่า'],
 ['เลือกว่าปีกหินจะเฝ้าประตูใด','คำสั่งเก่าให้ไล่ทุกผู้มาเยือน แต่หินตื่นแล้วมีเสียงของตน','เฝ้าป้อมตามตราเดิม','เปิดประตูให้ผู้หนีภัย','ถอนตัวจากฐานแล้วเลือกทางเอง'],
 ['เห็นมากกว่าผู้ท้าประลอง','ตาเดียวเห็นแรงที่อีกฝ่ายซ่อน แต่ไม่จำเป็นต้องชนะทุกครั้ง','รับศึกเพื่อเกียรติถ้ำ','ใช้แรงปกป้องผู้ที่ถูกท้าทาย','มองโลกโดยไม่ยืมสายตาของเผ่า'],
 ['ให้ปริศนาเป็นประตูแทนคุก','ผู้ตอบไม่ได้อาจเป็นผู้หิว ไม่ใช่ศัตรูของทราย','รักษาพรมแดนด้วยคำท้า','ใช้ปริศนาสอนทางโอเอซิส','ทิ้งประตูที่บรรพชนสั่งให้เฝ้า'],
 ['ไม่ให้เขาสั่งตัดสินทุกชีวิต','กลิ่นคำโกหกชวนขับไล่ แต่ความกลัวก็ทำให้คนปิดคำจริง','คุมเขตบริสุทธิ์ของฝูง','ฟังผู้พลัดถิ่นก่อนตัดสิน','เลือกถิ่นที่ไม่ต้องพิพากษาใคร'],
 ['พายุซึ่งฝูงเรียกกลับได้','ไฟฟ้าในขนปลุกให้ท้าฟ้า แต่การระบายแรงอาจทำรังอื่นพัง','ขยายเขตฟ้าคำราม','นำพายุออกจากทางอพยพ','ปล่อยเสียงซึ่งไม่ประกาศอำนาจ'],
 ['มีทะเลที่เสียงตนไม่กลบทุกฝูง','ความหิวพาไปหาฝูงใหญ่ แต่พลังมหาศาลก็ช่วยบังคลื่นได้','ครองแนวล่าแห่งสมุทร','คุมเขตล่าไม่ให้ทับแหล่งฟัก','ดำน้ำลึกพ้นคำเรียกบัลลังก์'],
 ['มีผู้เข้าใกล้โดยไม่ต้องล่อเป็นเหยื่อ','ร่างเลียนสิ่งที่ใครอยากได้ แต่คุณอาจอยากให้เขาเห็นตัวจริง','ล่อเหยื่อรักษาเขตพัก','เปิดรูปจริงให้ผู้เดินทางรู้ทัน','เลือกสิ่งที่จะเลียนโดยไม่รอเหยื่อ'],
 ['มีท่าทางที่ไม่มาจากผู้ชัก','ข้อต่อจำแรงเชือกเก่า แต่ร่างที่ตื่นเลือกจังหวะได้','สืบบทที่ช่างตั้งไว้','ช่วยตุ๊กตาที่หลุดจากผู้ชัก','ตัดท่าซ้ำแล้วสร้างท่าของตน'],
 ['จำโลกโดยไม่เกณฑ์คนตายทั้งหมด','แกนรับเสียงวิญญาณได้ แต่การฟังไม่เท่ากับมีสิทธิ์สั่ง','รวมกองคืนชีพคุ้มแกน','ปล่อยผู้ตายที่ไม่ยินยอมผูกพัน','หาวิธีอยู่โดยไม่ยืมชีวิตใคร'],
 ['เลือกทางที่ไม่ต้องถือคำสั่งประหาร','เสียงจากศีรษะเก่าชวนกลับสนาม แต่ผู้ถือร่างยังเลือกวางคมได้','สืบหน้าที่กองอัศวินคืนชีพ','นำผู้ไร้ศีรษะกลับเขตพัก','ออกจากตราเจ้านายเดิม'],
 ['ให้เสียงร้องพาผู้ฟังกลับได้','เสียงสูญเสียอาจทำให้คนหลง แต่ก็เตือนทางอันตรายได้','คุมเขตวิญญาณด้วยเสียงคร่ำ','ร้องนำผู้หลงออกจากถิ่นตาย','เลือกความเงียบโดยไม่ลืมตน'],
 ['มีคำขอที่ไม่ใช่โซ่ของตน','คำขอให้พลังและจองจำได้ ผู้ให้พรจึงต้องมีสิทธิ์ปฏิเสธ','สะสมพันธะให้เผ่าลมทราย','ทำพรที่ผู้ขอรู้ราคาจริง','ถอนตนจากภาชนะผูกมัด'],
 ['เหลือเปลวโดยไม่เผาผู้เข้ามาใกล้','แกนเทียนต้องเชื้อ แต่ไม่จำเป็นต้องใช้สิ่งมีชีวิตเป็นฟืน','รักษาไฟประจำวงศ์','แบ่งแสงโดยเว้นระยะปลอดภัย','ตามหาเชื้อที่ไม่ขึ้นกับผู้จุด'],
 ['รวมรูปโดยไม่เข้าปอดทุกผู้ผ่าน','ลมพาร่างแผ่ไกล แต่การเข้าไปในร่างอื่นไม่ใช่ทางเดียวที่จะอยู่','ครอบแนวลมของเผ่า','เว้นอากาศสะอาดให้ร่างมีปอด','เลือกแกนที่ไม่ผูกกับเตาใคร'],
 ['อยู่กับความหิวโดยไม่ยอมให้มันสั่ง','กลิ่นอาหารกรีดแกนจนอยากกลืน แต่คุณยังเลือกช้าลงได้','ล่าตามพันธะท้องว่าง','แย่งเฉพาะเสบียงที่ไม่มีผู้พึ่ง','หาวิธีดับหิวโดยไม่ล่าคน'],
 ['มีจังหวะนอกหน้าปัดผู้สร้าง','เฟืองตอบเวลาเดิม แต่เจตจำนงไม่จำเป็นต้องตรงทุกเข็ม','รักษาเครื่องเวลาของนคร','ปรับจังหวะให้ร่างต่างแบบอยู่ร่วม','หยุดเฟืองหนึ่งชุดเพื่อฟังตน'],
 ['คงผลึกโดยไม่ให้ทุกสิ่งหนาวตาม','ความอุ่นทำให้ร่างเลือน แต่ชีวิตอื่นก็ต้องแดด','รักษาแนวหิมะของแกน','เปิดเขตอุ่นข้างเขตเย็น','ออกค้นร่างที่ไม่ยึดฤดูเดียว'],
 ['แผ่กิ่งโดยไม่ปิดกระแสของผู้อื่น','อาหารมากับน้ำ แต่กิ่งที่โตเกินอาจบังกิ่งอ่อน','ขยายแนวปะการังของรัง','เว้นกระแสให้หลายสายพันธุ์','แตกหน่อไปพ้นคำสั่งแกนกลาง'],
 ['ได้ยินตนท่ามกลางจังหวะรัง','หนวดรับคำสั่งพร้อมกัน แต่แรงขาไม่จำเป็นต้องตามทุกครั้ง','รับหน้าที่ของกองรัง','ต่อรองการร่วมงานกับรังอื่น','แยกฝีเท้าโดยไม่ตัดทางกลับ'],
 ['คลายเกล็ดได้แม้มีเงาใหญ่','ความกลัวสั่งให้ม้วนตัว แต่กลิ่นคุ้นเคยอาจชวนให้ออกดู','รักษาโพรงและแนวหากิน','เตือนสัตว์เล็กก่อนผู้ล่ามา','ออกค้นทางที่ไม่ต้องม้วนตัวตลอด']
 ];
 const catalog=rows.map(([name,pressure,inherit,coexist,self],race)=>({race,name,pressure,paths:{inherit,coexist,self}}));
 const cap=(n,a=0,b=100)=>Math.max(a,Math.min(b,n)),hash=(s,k)=>{let n=Math.imul((s.seed^k)>>>0,2654435761);return(n^(n>>>16))>>>0};
 function ensure(s,fresh=false){if(!s.raceDrives)s.raceDrives={version:1,stance:null,lastChangeYear:-1,lastQuarter:-1,actionQuarter:-1,resource:75,legacyCash:!fresh&&(s.job!==null||!!s.livelihood?.business||(s.economy?.debt||0)>0),history:[]};return s.raceDrives}
 const profile=s=>catalog[typeof s==='number'?s:s.race];
 function cashless(s){return Ecology.native(s)&&!ensure(s).legacyCash}
 function choose(s,stance){const r=ensure(s);if(!['inherit','coexist','self'].includes(stance)||s.dead||!s.accepted||s.calendar?.pending||s.outcome||Engine.biological(s)<6||r.stance===stance||r.lastChangeYear===WorldTimeline.year(s))return false;r.stance=stance;r.lastChangeYear=WorldTimeline.year(s);r.history.push({age:s.age,stance});r.history=r.history.slice(-16);Narrative.append(s,{title:profile(s).paths[stance],paragraphs:[profile(s).pressure+' คุณเลือก'+profile(s).paths[stance]+'ในช่วงนี้ และยังเปลี่ยนทางในปีต่อไปได้'],kind:'decision',key:'race-way-'+s.calendar.count,ecology:true,scene:Ecology.profile(s).scene});return true}
 function observe(s,e,c){if(e.driveOnly===undefined)return;const r=ensure(s);r.stance=c.driveStance;r.lastChangeYear=WorldTimeline.year(s);r.history.push({age:s.age,stance:c.driveStance});r.history=r.history.slice(-16)}
 function next(s){return ensure(s).stance===null?EVENTS.find(e=>e.driveOnly===s.race&&Engine.eligible(s,e)):null}
 function matches(s,e){return e.driveOnly===undefined||e.driveOnly===s.race&&ensure(s).stance===null}
 function quarter(s){const r=ensure(s),q=s.calendar.count;if(r.lastQuarter===q||s.dead)return;r.lastQuarter=q;if(!cashless(s))return;const world=WorldTimeline.impact(s),supply=world.local&&world.price>1.15?-2:1,effort=s.lifeChoices?.yearFocus==='health'?2:0;r.resource=cap(r.resource+supply+effort-(world.severity>.3?1.5:0));if(r.resource<25){s.joy=cap(s.joy-.7);s.health=Math.max(1,s.health-.4)}if(q%12===0&&r.resource<30)Narrative.append(s,{title:'แหล่งดำรงชีวิตที่เริ่มไม่พอ',paragraphs:['สภาพของ'+Ecology.profile(s).label+'ทำให้สิ่งที่ร่างต้องใช้ลดลง คุณต้องเลือกระหว่างแนวพักเดิมกับทางสำรวจใหม่'],kind:'home',key:'native-scarcity-'+q,ecology:true,scene:Ecology.profile(s).scene,tone:'loss'})}
 function act(s,id){const r=ensure(s),q=s.calendar?.count||0;if(!cashless(s)||s.dead||!s.accepted||s.calendar?.pending||s.outcome||r.actionQuarter===q||Engine.biological(s)<6||!['forage','claim','share'].includes(id))return false;if(id==='claim'&&Engine.biological(s)<18||id==='share'&&r.resource<8||id==='forage'&&s.health<6)return false;r.actionQuarter=q;let text;if(id==='forage'){r.resource=cap(r.resource+14);s.health=Math.max(1,s.health-1);text='คุณใช้'+Ecology.profile(s).sense+'หาแหล่งดำรงชีวิต ร่างได้กำลังเพิ่มแต่ต้องพักหลังสำรวจ'}if(id==='claim'){r.resource=cap(r.resource+20);s.bond=cap(s.bond-3);text='คุณส่งสัญญาณประกาศเขตและใช้แรงขับผู้มาใช้แหล่งเดียวกันออก กลุ่มของคุณได้ส่วนเพิ่ม แต่ผู้ถูกไล่ต้องหาทางอื่น'}if(id==='share'){r.resource=cap(r.resource-8);s.bond=cap(s.bond+3);text='คุณเว้นส่วนหนึ่งของแหล่งดำรงชีวิตให้ร่างอื่นได้ใช้ ก่อนส่งสัญญาณขอบเขตที่ตกลงกัน'}const pair=[9,36].includes(s.race)?'dragon-quarry':Species.isDemon(s.race)?'ash-border':null;if(pair&&id!=='forage')WorldRelations.nudge(s,pair,id==='claim'?-4:3,id==='claim'?2:-2,text);Narrative.append(s,{title:{forage:'ตามสัญญาณของแหล่งดำรงชีวิต',claim:'เขตที่คุณเลือกประกาศ',share:'พื้นที่ที่เลือกเว้นให้ผู้อื่น'}[id],paragraphs:[text],kind:'interaction',key:'native-resource-'+q,ecology:true,scene:Ecology.profile(s).scene});return true}
 function nativePage(s){const r=ensure(s),p=profile(s),env=Ecology.profile(s),age=Engine.biological(s),n=hash(s,s.calendar?.count??s.turn);if(age<6)return null;const stance=r.stance||'self',texts={inherit:[p.pressure,'คุณรับรู้'+env.sense+'ก่อนลอง'+env.learningSkill+'ในแนวที่กลุ่มคุ้นเคย'],coexist:[p.pressure,'แนวพักมีสัญญาณของร่างต่างแบบ คุณเว้นระยะจนแยกสัญญาณทักออกจากการท้าทายได้'],self:[p.pressure,'คุณสำรวจส่วนที่รับไหวด้วย'+env.sense+' แล้วเลือกว่าจะกลับไปหาใครหรืออยู่เงียบ ๆ อีกช่วง']},line=texts[stance][n%2];return {title:n%2?p.paths[stance]:p.name,paragraphs:[line],kind:'heritage',key:'drive-day-'+s.race+'-'+stance+'-'+n%4,ecology:true,scene:env.scene}}
 function familyRoles(s,onlyId){const p=Ecology.profile(s);if(!p.strict)return;for(const m of s.household?.members||[]){if(onlyId&&m.id!==onlyId)continue;if(Ecology.profile(m.race).strict)m.trait='จำ'+Ecology.profile(m.race).sense+'และส่งสัญญาณก่อนเข้าถิ่น';if(p.origin==='spore')m.role=m.id==='guardian'?'ใยต้นทาง · ผู้เพาะหัวเชื้อ':m.id.startsWith('child-')?'หน่อร่วมใย':m.id==='partner'?'คู่เชื่อมใย':'สมาชิกเครือใยเดียวกัน';else if(['awaken','crystal','ink','sand','ember','seed','bud'].includes(p.origin))m.role=m.id==='guardian'?'ผู้ประคองแกนแรกตื่น':m.id==='partner'?'คู่ผูกพันของจุดยึด':m.id.startsWith('child-')?'แกนอ่อนที่รับดูแล':'ผู้ร่วมแหล่งก่อรูป';else if(['egg','roe'].includes(p.origin)&&m.id==='guardian')m.role='ผู้เฝ้าการฟักและแนวพัก';if(p.strict&&m.id==='partner')m.occupation=Ecology.occupation(m.race,m.id)}}
 function lastRest(s){const p=Ecology.profile(s);return p.body==='shade'?'จุดยึดค่อย ๆ คลาย จนขอบร่างไม่กลับมารวมอีก':p.body==='gel'?'แกนหยุดรักษาขอบร่างและคืนสู่แหล่งที่เคยเลี้ยงชีวิต':p.body==='roots'?'แกนส่งสัญญาณครั้งสุดท้ายก่อนคืนสู่เครือถิ่น':p.origin==='awaken'||p.origin==='crystal'?'แรงในแกนค่อย ๆ เงียบลงหลังคงร่างมายาวนาน':'พักครั้งสุดท้ายในแนวถิ่นที่คุ้นเคย'}
 function migrate(s){if(s.raceDrives)return;ensure(s);if(!Ecology.profile(s).strict||!cashless(s))return;const bad=new Set;for(const e of s.diary?.entries||[]){const text=(e.paragraphs||[]).join(' ');if(/หน้าต่าง|โต๊ะอาหาร|ห้องเรียน|ยกมือถาม|รองเท้า/.test(text)||cashless(s)&&['work','finance'].includes(e.kind)){e.legacyEcologyMismatch=true;bad.add(e.key)}}for(const e of s.lifeLegacy?.entries||[])if(bad.has(e.key))e.legacyEcologyMismatch=true;for(const list of [s.diary?.memories,s.stories?.memories])if(Array.isArray(list))for(let i=list.length-1;i>=0;i--)if(bad.has('decision-'+list[i].id)||bad.has(list[i].id))list.splice(i,1)}
 function nativeRank(s){if(typeof SpeciesSociety!=='undefined'&&s.race!==0)return SpeciesSociety.label(s);return ['ผู้พ้นแนวถิ่น','ผู้ใช้แหล่งพักร่วม','ผู้รู้ทางของถิ่น','ผู้แลกสัญญาณข้ามถิ่น','ผู้จำทางเก่า','ผู้เฝ้าแนวฝูง','ผู้สืบเขตพักใหญ่','ผู้สืบแกนหรือรังเก่า'][s.rank]}
 function valid(s){const r=s.raceDrives;if(r===undefined)return true;const n=(v,a,b)=>Number.isFinite(v)&&v>=a&&v<=b;return r&&r.version===1&&[null,'inherit','coexist','self'].includes(r.stance)&&Number.isInteger(r.lastChangeYear)&&n(r.lastChangeYear,-1,120000)&&Number.isInteger(r.lastQuarter)&&n(r.lastQuarter,-1,20000)&&n(r.resource,0,100)&&typeof r.legacyCash==='boolean'&&(r.actionQuarter===undefined||Number.isInteger(r.actionQuarter)&&n(r.actionQuarter,-1,20000))&&Array.isArray(r.history)&&r.history.length<=16&&r.history.every(x=>n(x.age,0,s.age)&&['inherit','coexist','self'].includes(x.stance))}
 function install(){if(catalog.length!==RACES.length)throw Error('Race drive catalog incomplete');for(const p of catalog)EVENTS.push({id:'drive-choice-'+p.race,title:p.name,text:p.pressure+' คุณอยากวางทางของตนอย่างไร',min:6,once:true,certain:true,lifeOpportunity:true,ecology:true,scene:Ecology.profile(p.race).scene,driveOnly:p.race,choices:Object.entries(p.paths).map(([driveStance,label])=>({label,driveStance,effect:{},risk:0,hint:'เปลี่ยนทิศทางเรื่องเล่า · ไม่มีแต้มจากการกดเลือก',success:'คุณเลือก'+label+' โดยไม่ได้สาบานว่าต้องเดินทางนี้ไปตลอดชีวิต'}))})}
 return {catalog,profile,ensure,cashless,choose,observe,next,matches,quarter,act,nativePage,familyRoles,migrate,valid,install,nativeRank,lastRest};
})();

