/* housing-controls.js */
'use strict';
const HousingUI=(()=>{
 const num=n=>n.toLocaleString('th-TH',{maximumFractionDigits:0});
 function panel(s){const h=Housing.ensure(s);return `<button class="panel housing-overview" id="openHousing"><span class="eyebrow">ถิ่นพักและสิ่งที่ต้องดูแล</span><strong>${h.owned?esc(Housing.option(s,h.tier).name):RaceDrives.cashless(s)?'พักในถิ่นที่กลุ่มดูแลร่วมกัน':'ยังแบ่งที่พักกับครอบครัวหรือเช่าอยู่'}</strong><span>${h.owned?Housing.option(s,h.tier).annual.toLocaleString('th-TH')+' '+(h.native?'แหล่งถิ่น':'ทอง')+' ต่อปี':'เลือกดูระดับที่พักและภาระรายปี'} · ดูที่พัก ↗</span></button>`}
 function open(){const s=state,h=Housing.ensure(s),native=RaceDrives.cashless(s);modal(`<section class="housing-dialog"><span class="eyebrow">ปี ${WorldTimeline.year(s)} · ที่พักของชีวิตนี้</span><h2>${h.owned?esc(Housing.option(s,h.tier).name):'ที่ที่อยากกลับมาพัก'}</h2><p>${native?'ความกว้างของเขตพักใช้ทั้งสิทธิร่วมถิ่น แหล่งดำรงชีวิต และแรงดูแลต่อเนื่อง':'ซื้อสดหรือขายที่พักเดิมสมทบเมื่อขยับระดับ ค่าภาษี ประกันและบำรุงคิดทุกปี แบ่งจ่ายตามเวลาที่ผ่านไป'}</p><p>${native?'แหล่งถิ่น '+Math.round(s.raceDrives.resource)+'/100':'เงินพร้อมใช้ '+num(s.gold)+' ทอง'+(h.owned?' · ที่พักเดิมขายสุทธิได้ '+num(Housing.value(s))+' ทอง':'')}</p><div class="housing-options">${Housing.catalog.map((_,i)=>{const o=Housing.option(s,i),why=Housing.reason(s,i);return `<article class="${h.tier===i?'current':''}"><canvas width="160" height="72" data-home-preview="${i}" role="img" aria-label="ที่พักระดับ ${i+1}"></canvas><span class="eyebrow">ระดับ ${i+1}/5</span><h3>${esc(o.name)}</h3><p>${native?'พื้นที่พักและจุดหลบเพิ่มตามรูปกาย ต้องคุ้มครองและฟื้นแหล่งถิ่น':' '+esc(o.description)}</p><strong>${num(o.cost)} ${o.unit}</strong><p class="housing-upkeep">ภาระรายปี ${num(o.annual)} ${o.unit}</p>${why?`<small>${esc(why)}</small>`:''}<button class="secondary" data-buy-housing="${i}" ${why?'disabled':''}>${h.owned?'ขายที่พักเดิมและขยับระดับ':'จัดที่พักระดับนี้'}</button></article>`}).join('')}</div>${h.owned&&!h.native?`<button class="secondary" id="sellHousing" ${!LifeSpending.allowed(s)||Engine.biological(s)<18?'disabled':''}>ตรวจสอบการขายที่พักเดิม →</button>`:''}</section>`);document.querySelectorAll('[data-buy-housing]').forEach(b=>b.onclick=()=>{if(Housing.buy(s,Number(b.dataset.buyHousing))){save();clock.reset();render();open();toast('ที่พักใหม่มีภาระที่ต้องดูแลทุกปี')}});if($('#sellHousing'))$('#sellHousing').onclick=()=>{modal(`<h2>ส่งต่อที่พักหลังนี้?</h2><p>รับสุทธิ ${num(Housing.value(s))} ทองหลังหักค่าธรรมเนียม แล้วกลับไปจ่ายค่าที่พักตามแผนเดิม</p><button class="secondary" id="keepHousing">เก็บไว้</button><button class="secondary" id="confirmSellHousing">ขายที่พัก</button>`);$('#keepHousing').onclick=open;$('#confirmSellHousing').onclick=()=>{if(Housing.sell(s)){save();clock.reset();render();open()}}};document.querySelectorAll('[data-home-preview]').forEach(c=>paint(c,s,Number(c.dataset.homePreview)))}
 function paint(canvas,s,tier){const c=canvas.getContext('2d'),p=Ecology.profile(s);c.imageSmoothingEnabled=false;c.fillStyle=p.water?'#8caeb0':p.habitat==='cave'?'#8e9b83':'#b8c6ab';c.fillRect(0,0,160,72);c.fillStyle=p.water?'#637f82':'#747b5b';c.fillRect(0,58,160,14);if(s.race!==0&&p.strict){const w=50+tier*18,x=(160-w)/2;c.fillStyle='#63766b';for(let k=0;k<6;k++)c.fillRect(x+k*w/6,36-Math.min(k,5-k)*5,w/6+1,23+Math.min(k,5-k)*5);c.fillStyle='#344f4b';c.fillRect(x+12,41,w-24,17);for(let k=0;k<=tier;k++){c.fillStyle='#b3c5a0';c.fillRect(x+17+k*19,47,4,4)}return}const w=42+tier*20,x=(160-w)/2;c.fillStyle=['#d0bf92','#ddc9a1','#d9c9b3','#d3c3a6','#e2d4b4'][tier];c.fillRect(x,30-tier*3,w,29+tier*3);c.fillStyle='#6c685a';c.fillRect(x-5,24-tier*3,w+10,7);for(let k=0;k<=tier;k++){c.fillStyle='#6d8c89';c.fillRect(x+7+k*20,35-tier*3,9,9);c.fillStyle='#c6b476';c.fillRect(x+7+k*20,40-tier*3,9,2)}c.fillStyle='#68654f';c.fillRect(76,46,10,13);if(tier>=2){c.fillStyle='#91a084';c.fillRect(x-8,43,7,17);c.fillRect(x+w+1,43,7,17)}if(tier>=3){c.fillStyle='#aaa08b';c.fillRect(x-7,37,5,22);c.fillRect(x+w+2,37,5,22)}if(tier===4){c.fillStyle='#8e805f';c.fillRect(23,51,3,12);c.fillRect(134,51,3,12)}}
 function bind(){if($('#openHousing'))$('#openHousing').onclick=open}
 return {panel,open,paint,bind};
})();

/* adventure-controls.js */
'use strict';
Adventures.install();
const AdventureUI=(()=>{
 const num=n=>n.toLocaleString('th-TH',{maximumFractionDigits:0});
 function refresh(message){save();clock.reset();render();open();if(message)toast(message)}
 function panel(s){const a=Adventures.ensure(s),active=a.active,m=active&&Adventures.get(active.id);return `<section class="panel adventure-overview"><div><span class="eyebrow">สมาคมนักผจญภัย · หลายเผ่าร่วมคณะ</span><h3>${a.member?'แรงค์ '+Adventures.ranks[a.rank]+' · '+num(a.xp)+' ประสบการณ์':'ทางที่ต้องเลือกด้วยตนเอง'}</h3><p>${m?esc(m.name)+' · '+['กำลังเข้าถึงเขตงาน','พบสิ่งเฝ้าทาง','เตรียมกลับและแบ่งส่วน'][active.stage]:a.member?'เสบียงและการพักฟื้นสำคัญพอ ๆ กับค่าจ้าง':'สำรวจดันเจี้ยน ป่าลึก ทางน้ำ และรอยแยกตามรูปกาย'}</p></div><button class="secondary" id="openAdventures">${m?'ดูงานที่รับไว้':'ดูทะเบียนและงาน'} →</button></section>`}
 function open(){const s=state,a=Adventures.ensure(s),native=RaceDrives.cashless(s),active=a.active,m=active&&Adventures.get(active.id),locked=Adventures.locked(s);modal(`<section class="adventure-dialog"><span class="eyebrow">ปี ${WorldTimeline.year(s)} · ${esc(RACES[s.race][0])}</span><h2>สมาคมนักผจญภัย</h2><p>${esc(Adventures.role(s))}</p><div class="adventure-rank"><b>${Adventures.ranks[a.rank]}</b><div><strong>${num(a.xp)} ประสบการณ์</strong><progress max="${Adventures.thresholds[Math.min(7,a.rank+1)]||1}" value="${Math.min(a.xp,Adventures.thresholds[Math.min(7,a.rank+1)])}" aria-label="ประสบการณ์นักผจญภัย"></progress><small>สำเร็จ ${a.completed} งาน · ถอนตัว ${a.failed} งาน</small></div></div><p class="adventure-note">แรงค์สมาคมแยกจาก Tier เผ่าและชนชั้น งานที่รับผิดชอบสูงต้องมีทั้งประสบการณ์และรายงานสำเร็จ ไม่มีเงินเดือนจากการถือทะเบียน ค่าสมาชิก ${native?'แหล่งถิ่น 2':'120 ทอง'} ต่อปี</p>${!a.member?`<button class="primary" id="joinAdventures" ${locked?'disabled':''}>ลงทะเบียนแรงค์ F · ไม่มีค่าเข้า</button>${Engine.biological(s)<16?'<p class="adventure-note">เริ่มร่วมคณะได้เมื่อถึงวัยฝึกงานของเผ่า</p>':''}`:''}${a.member&&m?`<section class="adventure-active"><span class="eyebrow">งานที่รับไว้ · ช่วง ${active.stage+1}/3</span><h3>${esc(m.name)}</h3><p>${esc(m.brief)}</p><p class="adventure-note">ออกเดินทางแล้ว · ระบบจะเล่าเหตุเมื่อถึงช่วงสำรวจ คุณพักหรือถอนตัวได้ ค่าของที่ใช้แล้วไม่คืน</p><button class="secondary" id="withdrawAdventure" ${locked?'disabled':''}>ถอนตัวและส่งรายงานกลับ</button></section>`:''}${a.member&&!m?`<h3>งานที่มีคณะรับร่วมในช่วงนี้</h3><div class="adventure-board">${Adventures.board(s).map(m=>{const why=Adventures.reason(s,m),risk=Math.round(Adventures.chance(s,m)*100);return `<article><span class="eyebrow">งานแรงค์ ${Adventures.ranks[m.rank]}</span><h3>${esc(m.name)}</h3><p>${esc(m.brief)}</p><dl><div><dt>ส่วนแบ่งเมื่อสำเร็จ</dt><dd>${native?'แหล่งถิ่น +12':num(m.reward)+' ทองก่อนภาษี 18%'}</dd></div><div><dt>เตรียมเสบียง</dt><dd>${native?'แหล่งถิ่น −'+(6+m.rank*2):num(m.cost)+' ทอง'}</dd></div></dl><small class="adventure-risk">โอกาสเสียเปรียบโดยประมาณ ${risk}% · บาดเจ็บ คำสาป หรือเสียชีวิตต่อเนื่องเป็นไปได้</small>${why?`<p class="adventure-note">${esc(why)}</p>`:''}<div class="adventure-actions"><button class="secondary" data-contract="${m.id}" ${why||native&&s.raceDrives.resource<6+m.rank*2||!native&&s.gold<m.cost?'disabled':''}>เตรียมเองและรับงาน</button>${!native?`<button class="secondary" data-contract-advance="${m.id}" ${why?'disabled':''}>รับเสบียงล่วงหน้า · คืน ${num(Math.round(m.cost*1.15))} ทอง</button>`:''}</div></article>`}).join('')}</div><p class="adventure-note">การสำรวจหนึ่งช่วงใช้เวลาประมาณสามเดือนและมีหลายการตัดสินใจในช่วงนั้น หลังกลับต้องพักอย่างน้อยหนึ่งช่วง รายได้งานนอกเวลาต้องหักเวลาที่ออกสำรวจ</p>`:''}${a.member?`${!native?'<button class="secondary" id="guildBudget">บัญชีรายปีและแผนที่พักรวมสมาคม →</button>':''}<h3>เครื่องช่วยและสิ่งคุ้มร่าง</h3><p>สภาพ ${Math.round(a.gear.condition)}/100 · รูปแบบเข้ากับร่างของ${esc(RACES[s.race][0])}</p><div class="adventure-gear">${[['weapon','การรับมือสิ่งขวางทาง'],['ward','สิ่งคุ้มร่างและจุดยึด'],['kit','เครื่องช่วยสำรวจ']].map(([id,name])=>`<button class="secondary" data-adventure-gear="${id}" ${locked||!!m||a.gear[id]>=3?'disabled':''}><b>${name} ${a.gear[id]}/3</b><small>${native?'แหล่งถิ่น '+(12+a.gear[id]*8):num([450,1800,6500][a.gear[id]]||0)+' ทอง'} · ใช้หนึ่งช่วงเตรียมตัว</small></button>`).join('')}<button class="secondary" data-adventure-gear="repair" ${locked||!!m||a.gear.condition>=100?'disabled':''}>ซ่อมและตรวจสภาพ · ${native?'แหล่งถิ่น 8':num(Math.round(180+(100-a.gear.condition)*8))+' ทอง'}</button></div>`:''}${a.history.length?`<details><summary>งานที่เคยกลับมาเล่า</summary>${a.history.map(h=>`<p><small>ปี ${h.year} · อายุ ${h.age}</small><br>${esc(h.text)}</p>`).join('')}</details>`:''}<p id="adventureError" class="adventure-risk" role="status"></p></section>`);if($('#guildBudget'))$('#guildBudget').onclick=EpochUI.money;if($('#joinAdventures'))$('#joinAdventures').onclick=()=>{if(Adventures.join(s))refresh('ชื่อของคุณอยู่ในทะเบียนแล้ว')};for(const [sel,advance] of [['[data-contract]',false],['[data-contract-advance]',true]])document.querySelectorAll(sel).forEach(b=>b.onclick=()=>{if(Adventures.accept(s,advance?b.dataset.contractAdvance:b.dataset.contract,advance))refresh('เตรียมคณะไว้แล้ว ชีวิตจะเล่าการเดินทางเมื่อเวลาเดินต่อ');else $('#adventureError').textContent='ตรวจเสบียง สิทธิ และเรื่องที่ยังค้างอยู่ก่อน'});document.querySelectorAll('[data-adventure-gear]').forEach(b=>b.onclick=()=>{if(Adventures.train(s,b.dataset.adventureGear))refresh('บันทึกการเตรียมตัวแล้ว');else $('#adventureError').textContent='ทุนหรือแหล่งถิ่นไม่พอ หรือเตรียมตัวในช่วงนี้แล้ว'});if($('#withdrawAdventure'))$('#withdrawAdventure').onclick=()=>{if(Adventures.withdraw(s))refresh('ส่งรายงานถอนตัวแล้ว')};}
 function bind(){if($('#openAdventures'))$('#openAdventures').onclick=open}
 return {panel,open,bind};
})();

/* life-economy-controls.js */
'use strict';
// Record net wallet flows not already itemized by the called subsystem.
(()=>{
 const flow=x=>x.gross-x.tax+x.support+x.otherIncome-x.expenses-x.otherSpend-x.principal+x.shortfall;
 function wrap(api,key){if(typeof api?.[key]!=='function')return;const original=api[key];api[key]=function(s,...args){const book=Economy.accounts(s).current,cash=s.gold,before=flow(book),result=original.call(this,s,...args);if(book===Economy.accounts(s).current){const delta=Math.round(((s.gold-cash)-(flow(book)-before))*100)/100;if(delta)Economy.record(s,delta>0?'otherIncome':'otherSpend',Math.abs(delta))}return result}}
 for(const [api,keys] of [[Simulation,['automatic']],[Engine,['apply']],[LifeSpending,['spend','sellHouse']],[LifeChoices,['tick','buyItem','sellItem','adoptPet','petAction']],[LifeProjects,['start','resume','quarter']],[LifeBonds,['act']],[HumanOrigins,['support']],[Livelihood,['quarter','open','manage']],[Economy,['action']]])for(const k of keys)wrap(api,k);
 EVENTS.push({id:'family-pocket-gift',title:'ส่วนที่ผู้ดูแลกันไว้ให้',text:'{relative}เรียกคุณมาคุยเรื่องส่วนแบ่งที่กันไว้ คุณรับไว้ หรือฝากให้ใช้กับส่วนจำเป็นของกลุ่มก่อนได้',min:6,max:18,lifeOpportunity:true,familyGift:true,ecology:true,certain:true,choices:[{label:'รับไว้และถามว่าควรกันไว้ใช้อะไร',hint:'ส่วนแบ่งมาจากเงินหรือแหล่งดำรงชีวิตของผู้ดูแลจริง',effect:{bond:1},acceptGift:true,success:'ผู้ดูแลบอกที่มาของส่วนแบ่งก่อนมอบให้คุณ'},{label:'ฝากไว้กับส่วนจำเป็นของกลุ่มก่อน',hint:'ไม่รับเงินส่วนตัว · ความสัมพันธ์ +3',effect:{bond:3},declineGift:true,success:'คุณฝากส่วนแบ่งไว้ในแหล่งสำรอง ผู้ดูแลรับฟังเหตุผลของคุณ'}]});
EVENTS.push({id:'household-endowment',title:'ส่วนแบ่งจากทุนเดิมของกลุ่ม',text:'ผู้รับรองในกลุ่มชวนคุยเรื่องส่วนแบ่งที่ผูกกับสิทธิและพันธะ',min:18,lifeOpportunity:true,familyEndowment:true,ecology:true,certain:true,choices:[{label:'รับส่วนแบ่งและรับฟังภาระของกลุ่ม',hint:'รับจากทุนเดิมจริง · ความไว้ใจและพันธะมีผล',effect:{},acceptPatron:true,success:'คุณรับส่วนแบ่งพร้อมหน้าที่ที่ยังเลือกว่าจะตอบอย่างไร'},{label:'ให้เก็บทุนไว้ดูแลส่วนจำเป็นก่อน',hint:'ไม่รับเงินส่วนตัว · ความสัมพันธ์ +3',effect:{bond:3},success:'คุณให้กลุ่มกันทุนไว้สำหรับผู้ที่ยังจำเป็นต้องใช้'}]});
})();

/* life-reel.js */
'use strict';
const LifeReel=(()=>{
 const cap=20,copy=x=>JSON.parse(JSON.stringify(x)),clean=(x,n)=>String(x||'').replace(/\s+/g,' ').trim().slice(0,n);
 function stage(s,age){const b=Engine.ageEquivalent(age,s.race);return b<4?'early':b<12?'child':b<18?'teen':b<40?'adult':b<60?'middle':'elder'}
 function weight(e){return e.key==='birth'||e.key==='life-end'?100:e.kind==='growth'?95:e.kind==='loss'?88:e.choice&&/human-path|project|love|family|society|office|faith|housing/.test(e.key||'')?86:e.choice?65:e.kind==='spending'&&e.key?.startsWith('housing-')?82:0}
 function page(e){return {key:clean(e.key||'page-'+e.id,160),title:clean(e.title,290),paragraphs:[clean(e.paragraphs?.[0]||e.summary,380)],choice:clean(e.choice,180),age:e.age||0,month:e.month||1,realm:e.realm,kind:e.kind||'memory',tone:e.tone||'neutral',scene:e.scene,weight:weight(e),...(VisualMemory.has(e)?{visual:copy(e.visual)}:{})}}
 function observe(s,e){const w=weight(e);if(!w)return;if(!s.lifeReel)s.lifeReel={version:1,frames:[]};const a=s.lifeReel.frames,p=page(e),prior=a.findIndex(x=>x.key===p.key);if(prior>=0)return;a.push(p);if(a.length>cap){let drop=-1;const unique=x=>a.filter(y=>stage(s,y.age)===stage(s,x.age)&&y.kind==='growth').length===1;for(let i=0;i<a.length;i++){const x=a[i];if(x.key==='birth'||x.key==='life-end'||x.kind==='growth'&&unique(x))continue;if(drop<0||x.weight<a[drop].weight||x.weight===a[drop].weight&&i<drop)drop=i}a.splice(drop<0?1:drop,1)}}
 function records(s){const byKey=new Map,put=e=>byKey.set(e.key+'@'+e.age+':'+e.month+':'+e.choice,e);for(const e of s.lifeLegacy?.entries||[])if(!e.legacyAgeMismatch&&!e.legacyEcologyMismatch)put(page(e));for(const e of [...(s.diary?.entries||[])].reverse())if(!e.legacyAgeMismatch&&!e.legacyEcologyMismatch)put(page(e));for(const e of s.lifeReel?.frames||[])put(copy(e));return [...byKey.values()].filter(e=>e.age<=s.age).sort((a,b)=>a.age-b.age||a.month-b.month)}
 function slides(s){const all=records(s),chosen=new Map,add=e=>{if(e)chosen.set(e.key,e)};add(all.find(e=>e.key==='birth'));for(const k of ['early','child','teen','adult','middle','elder'])add(all.find(e=>e.kind==='growth'&&stage(s,e.age)===k));for(const e of all.filter(e=>e.choice||e.kind==='loss'||e.key.startsWith('housing-')).sort((a,b)=>b.weight-a.weight).slice(0,9))add(e);if(!chosen.size&&all.length)add(all[0]);const list=[...chosen.values()].filter(e=>e.key!=='life-end').sort((a,b)=>a.age-b.age||a.month-b.month).slice(0,16);const r=LifeLegacy.summary(s);if(r.people.length||r.departed.length)list.push({key:'reel-people',title:'คนที่มีความหมายในชีวิตนี้',paragraphs:[...r.people,...r.departed].slice(0,3).map(p=>p.name+' · '+clean(p.text,110)),age:s.age,month:1,realm:s.kingdom,kind:'memory'});const death=all.find(e=>e.key==='life-end');list.push(death?{...death,paragraphs:[s.cause||death.paragraphs[0]]}:{key:'reel-farewell',title:'หน้าสุดท้ายของ '+s.name,paragraphs:[s.cause||'ชีวิตนี้ถูกเก็บไว้ในบันทึกแล้ว'],age:s.age,month:1,realm:s.kingdom,kind:'loss'});return list}
 function valid(s){const r=s.lifeReel;if(r===undefined)return true;return r&&r.version===1&&Array.isArray(r.frames)&&r.frames.length<=cap&&new Set(r.frames.map(x=>x.key)).size===r.frames.length&&r.frames.every(e=>e&&typeof e.key==='string'&&e.key.length<=160&&typeof e.title==='string'&&e.title.length<=290&&Array.isArray(e.paragraphs)&&e.paragraphs.length===1&&typeof e.paragraphs[0]==='string'&&e.paragraphs[0].length<=380&&typeof e.choice==='string'&&e.choice.length<=180&&Number.isFinite(e.age)&&e.age>=0&&e.age<=s.age&&Number.isInteger(e.month)&&e.month>=1&&e.month<=12&&Number.isInteger(e.realm)&&e.realm>=0&&e.realm<KINGDOMS.length&&Number.isInteger(e.weight)&&e.weight>=0&&e.weight<=100&&(e.scene===undefined||typeof e.scene==='string'&&e.scene.length<100)&&(e.tone===undefined||typeof e.tone==='string'&&e.tone.length<40)&&typeof e.kind==='string'&&e.kind.length<40&&(e.visual===undefined||VisualMemory.validFrame(e.visual)))}
 return {observe,records,slides,valid,stage,cap};
})();

/* reel-controls.js */
'use strict';
const LifeReelUI=(()=>{
 const shown=new Set;let timer=null,token=0,pending=null;
 function stop(){clearTimeout(timer);timer=null;token++}
 function open(s){if(!s.dead)return;stop();const pages=LifeReel.slides(s);let index=0,paused=!!matchMedia('(prefers-reduced-motion: reduce)').matches;const own=token;shown.add(s.seed+':'+s.turn+':'+s.age);modal('<section class="life-reel" aria-label="สไลด์โชว์สรุปชีวิต"></section>');const root=$('#modalBody .life-reel');
 function paint(){if(!root.isConnected)return;clearTimeout(timer);$('#modal').scrollTop=0;const e=pages[index],has=VisualMemory.has(e),final=index===pages.length-1;root.innerHTML=`<div class="reel-top"><span>หนึ่งชีวิตของ ${esc(s.name)}</span><small>${index+1} / ${pages.length}</small></div><div class="reel-progress">${pages.map((_,i)=>`<i class="${i<=index?'seen':''}"></i>`).join('')}</div><figure><canvas width="480" height="180" id="reelScene" role="img" aria-label="ฉากจากบันทึกชีวิต"></canvas><figcaption>${has?'รูปลักษณ์ที่บันทึกไว้ในช่วงนั้น':e.kind==='loss'&&final?'ฉากอำลา':'ภาพสถานที่ประกอบ · ไม่มีภาพรูปลักษณ์เดิมในบันทึกนี้'}</figcaption></figure><span class="eyebrow">อายุ ${e.age} ปี${e.month?' · เดือน '+e.month:''} · ${esc(KINGDOMS[e.realm??s.kingdom][0])}</span><h2 tabindex="-1">${esc(e.title)}</h2>${e.choice?`<p class="reel-choice">คุณเลือก: ${esc(e.choice)}</p>`:''}${e.paragraphs.map(p=>`<p class="reel-story">${esc(StoryPresentation.short(p,220))}</p>`).join('')}<div class="reel-controls"><button class="secondary" id="reelPrev" ${index===0?'disabled':''}>← ก่อนหน้า</button><button class="secondary" id="reelPause" aria-pressed="${paused}">${paused?'▶ เล่นต่อ':'❚❚ พักอ่าน'}</button><button class="primary" id="reelNext">${final?'เก็บชีวิตนี้ไว้ →':'ถัดไป →'}</button></div><div class="reel-footer"><button id="reelDecisions">ดูการตัดสินใจที่บันทึกไว้</button><button id="reelExit">กลับไปการ์ดชีวิต</button></div>`;const canvas=root.querySelector('canvas');if(final&&e.kind==='loss')Illustration.drawScene(canvas,{...s,dead:true,calendar:{...s.calendar,pending:false},sceneOverride:(s.race?Ecology.profile(s).scene:'garden')+'-realm-'+s.kingdom},0);else VisualMemory.draw(canvas,s,e,0);root.querySelector('#reelPrev').onclick=()=>{index--;paint()};root.querySelector('#reelNext').onclick=()=>{if(final){stop();$('#modal').close()}else{index++;paint()}};root.querySelector('#reelPause').onclick=()=>{paused=!paused;paint()};root.querySelector('#reelExit').onclick=()=>{stop();$('#modal').close()};root.querySelector('#reelDecisions').onclick=()=>{stop();decisions(s)};if(!paused&&!final)timer=setTimeout(()=>{if(own===token&&root.isConnected&&$('#modal').open){index++;paint()}},9000)}paint();}
 function decisions(s){const records=LifeReel.records(s).filter(e=>e.choice);modal(`<section class="reel-decisions"><span class="eyebrow">การตัดสินใจที่ยังเก็บไว้ในบันทึก</span><h2>เส้นทางที่คุณเลือก</h2>${records.length?records.map(e=>`<article><small>อายุ ${e.age} ปี · เดือน ${e.month}</small><h3>${esc(e.title)}</h3><p class="reel-choice">${esc(e.choice)}</p><p>${esc(StoryPresentation.short(e.paragraphs[0],180))}</p></article>`).join(''):'<p>ชีวิตนี้ยังไม่มีการตัดสินใจที่บันทึกไว้</p>'}<p class="reel-fine">สมุดประจำวันเก็บจำนวนหน้าจำกัด เหตุการณ์สำคัญที่เก็บไว้จะยังอยู่ในสรุปชีวิต</p><button class="secondary" id="reelReplay">กลับไปดูสไลด์โชว์ →</button></section>`);$('#reelReplay').onclick=()=>open(s)}
 function attempt(){if(!pending)return;const s=pending;if(typeof state==='undefined'||state!==s||!s.dead||screen!=='playing'||tab!=='life'){pending=null;return}if($('#modal').open)return;pending=null;open(s)}
 function bind(root,s){root.querySelectorAll('[data-life-reel]').forEach(b=>b.onclick=()=>open(s));if(root===document&&s===state&&s.dead&&!shown.has(s.seed+':'+s.turn+':'+s.age)){pending=s;setTimeout(attempt,0)}}
 if(typeof document!=='undefined')document.querySelector('#modal').addEventListener('close',()=>{stop();setTimeout(attempt,0)});
 return {open,bind,stop};
})();

